export default [{"id":120,"question":"رجل تزوَّج من امرأةٍ سمعتها سيئة، وتوجد لها قضية بالمحكمة لسُوء خلقها، فما صحَّة هذا الزواج بالرغم من مُعارضة أهل الزوج لهذا الزواج؛ وذلك لسُوء أخلاقها؟ وهل تجوز مقاطعته من قبل أهله؟","title":"حكم الزواج بامرأة سيئة السمعة أو إمساكها","answer":"الجواب: الزواج صحيحٌ وإن كانت سيئة الأخلاق، ولكن إذا ما ناسبته أو أحبَّ والداه طلاقَها فيُطلِّقها طلقةً واحدةً ليَبَرَّ والديه، إذا كان والداه ذكرا شيئًا يُوجب الطلاق لسُوء سمعتها. أما إن كانت زانيةً معروفةً، ثبت أنها زانية، ولم تتب؛ فلا يجوز له أن يتزوجها، فالزانية ليس لأحدٍ أن يتزوجها حتى تتوب وتُعرف توبتها. أما مجرد سماع أنَّها سيئة الخلق، أو سيئة السمعة؛ فهذا لا يمنع الزواج، لكن المؤمن يتحرَّى المرأة حسنة السُّمعة، ولا يقدم على مَن سمعتها سيئة، بل يلتمس المرأة الصَّالحة التي سمعتها طيبة، مثلما قال النبيُّ ﷺ: فاظفر بذات الدين تربت يداك.\nفالإنسان ما يبحث عن التي سمعتها سيئة، لكن النكاح صحيحٌ، ويُشرع له أن يبحث عن المرأة الطيبة، التي سمعتها طيبة، وسمعة أهلها طيبة، هكذا ينبغي أن يتحرى.","link":"https://binbaz.org.sa/fatwas/3558/حكم-الزواج-بامراة-سيىة-السمعة-او-امساكها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0105.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":241,"question":"ما الموقف الشرعي من شخصٍ ربَّته جاريةُ والدته عندما كان عمره ست سنوات في الصِّغر، وحين كبر تزوَّجها زواجًا غير شرعيٍّ رغمًا عنها، فحملت منه، وأنجبت ولدًا، هل الولد يكون ابنًا له؟ وهل يحقّ لوالده أن يُنكره بعد وفاة الابن؟ وهل يحق لوالده أن يُنكر حقوق أبناء المُتوفى الذين يُعتبرون أحفادًا له؟ وهل يحقّ لهذا الوالد أن يُفرِّق في المُعاملة بين أبناء المُتوفى وبين أبناء أبنائه الآخرين؟ وما عاقبة ذلك على الرغم من أنني قد تعبتُ من المطالبة بالحقِّ ولكن الموقف كان يُقابل بلا مبالاة؟ أرجو إفادتي بما أوضحته لسماحتكم، جزاكم الله خيرًا.","title":"حكم الأولاد من زواج غير الشرعي، والتزوج ممن ربَّته","answer":"الجواب: المُربية لا تحرم على المُربَّى إذا كان ما بينهما رضاع ولا نسب: كالخادمة المملوكة، أو الخادمة غير المملوكة، ربَّته وأحسنت إليه؛ لأنها مُستأجرة أو متطوعة: كبنت عمِّه، أو بنت خاله، أو أجنبية ربَّت إنسانًا، ثم كبر وتزوَّجها؛ لا بأس، لكن كونه يتزوَّجها زواجًا غير شرعيٍّ بالزنا أو بغير وليٍّ شرعي؛ هذا لا يجوز، ما يُسمَّى: زواجًا هذا، هذا يُسمَّى: زنا، أو يُسمَّى: عقدًا فاسدًا، أو يُسمَّى: جرأة على الله، وتلاعبًا بالدين.\nفالحاصل أنَّ الذي اتَّخذ الخادمة التي ربَّته، ولم تُرضعه ولكن ربَّته، الذي تعدَّى عليها بالزنا أو بنكاحٍ غير شرعيٍّ؛ هذا لا يجوز، لكن يختلف: إن كان بنكاحٍ ظنَّه شرعيًّا فأولاده يُلحقون به، الأولاد يُنسبون إليه. أما إن كان زنًا فلا يُلحقون به، ولا يُنسبون إليه، بل يُنسبون إلى أمِّهم، ولا يجوز الاعتراف به بأنه ولدٌ له؛ لأنه من طريق الزنا. أما إن كان من طريق النِّكاح لكنه نكاح غير شرعيٍّ؛ بأن زوَّجها مَن ليس وليًّا لها، وظنُّوا أنه يصلح في ذلك -كما يوجد في بعض الدول- فهذا يكون نكاحًا غير شرعيٍّ، ويكون نكاحًا فاسدًا، والأولاد لاحقون به، لاحقون بأبيهم.","link":"https://binbaz.org.sa/fatwas/4121/حكم-الاولاد-من-زواج-غير-الشرعي-والتزوج-ممن-ربته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0281.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":302,"question":"رجلٌ لديه زوجتان، وأحد الزوجتين أحسن معاملةً لزوجها من الأخرى في المأكل والملبس والفراش، هل يجوز له أن يُفضِّلها على الأخرى؟","title":"حكم تفضيل إحدى الزوجتين لتقصير الأخرى","answer":"الجواب:\n\nالواجب عليه العدل بين الزوجتين، فالله سبحانه أوصى بالعدل، فعليه أن يعدل بينهما، وعليه أن يُعلِّم التي قد ساءت أخلاقُها أو قصَّرت في حقِّه، عليه أن يُعلِّمها ويُوجهها إلى الخير بالحكمة والكلام الطيب.\nوقد صحَّ عن رسول الله عليه الصلاة والسلام أنه قال: مَن كانت له امرأتان فمال إلى إحداهما جاء يوم القيامة وشِقّه مائل.\nفالواجب العدل بين الزوجات، قالت عائشة رضي الله عنها: كان النبيُّ ﷺ يقسم بين نسائه فيعدل، ويقول: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك.\n\nالشيء الذي يقدر عليه من القسمة بينهنَّ في الوقت وفي جميع أحواله وفي النَّفقة يفعل ذلك، أما ما لا يملك من جهة الحبِّ وما يتبعه من الوطء فهذا لا يلزمه فيها التعديل؛ فإنَّ الحبَّ بيد الله، ليس بيده هو، قد تكون هذه أحبَّ من هذه، وقد يشتهي هذه أكثر من هذه، وليس باختياره، هذا لا يلزم فيه العدل، ولا يأثم إذا جامع هذه أكثر من هذه، أو أحبَّ هذه أكثر من هذه؛ لأنَّ هذه أمور بيد الله، ليس في يد العبد.\nأما كونه يعدل فيها بإعطاء حقِّها من يومها وليلتها ونفقتها؛ فهذا واجبٌ، يقول النبيُّ ﷺ: ولهن عليكم رزقهنَّ وكسوتهنَّ بالمعروف، ما قال: والعدل بينهنَّ في الوطء، أو في الحب، لا، هذا ما يملكه الإنسانُ، ليس باختياره، لكن إذا كانت إحداهنَّ تُسيئ العشرة ولا تقوم بالواجب؛ يُعْلِمها ويُوجهها ويعمل معها ما يلزم من الإصلاح: من الوعظ والتَّذكير، أو الهجر، أو التأديب إذا دعت الحاجةُ إلى ذلك ولم ينفع الهجر ولم ينفع الوعظ.","link":"https://binbaz.org.sa/fatwas/4304/حكم-تفضيل-احدى-الزوجتين-لتقصير-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0351.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":313,"question":"(تعدد الزوجات) يتنكَّر لها الناسُ، وبعضهم يتصور أنَّها مُحرَّمة، والآن المجتمع يوجد به عنوسة خطيرة؟","title":"ما المنافع التي تحصل بتعدُّد الزوجات؟","answer":"الجواب: الله يقول جلَّ وعلا: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3]، فالأصل التَّعدد، وذلك في مصلحة الرجال والنِّساء، فالتعدد ينفع الرجل والمرأة، فالرجل قد لا تكفيه الواحدة، قد يكون عنده قوة الشَّهوة، فالواحدة لا تكفي، فيحتاج إلى ثنتين أو ثلاث أو أربع حتى يعفّ نفسه، وحتى يغضَّ بصره، وحتى يحصّن فرجه.\nوهكذا النساء في الحاجة إلى الرجال، فإذا لم يتزوج إلا واحدةً بقي كثيرٌ من النساء ما لهن أزواج، فإذا تعدد النّساء حصل للنِّساء مصلحة من ذلك، فكونها تكون عند زوجٍ ولو عنده غيرها خيرٌ لها من بقائها ليس عندها زوجٌ.\nفالمقصود أنَّ التَّعدد هو السُّنة، وهو الأصلح، وهو الأنفع للجميع، إذا كان الزوج يستطيع ذلك، فإن كونها تُعطى نصف رجلٍ أو ثلث رجلٍ أو ربع رجلٍ خيرٌ لها من بقائها عانسةً ليس عندها أحدٌ.\nفينبغي للنساء أن يعرفن هذا الأمر، وأن يحذرن الغيرة الضَّارة، وهكذا أولياؤهن، فلا ينبغي أن تمتنع المرأةُ من الزواج ممن عنده امرأة أو عنده امرأتان أو عنده ثلاث، لا، الله أباح له هذا، وفيه مصالح كثيرة للرجال والنساء، فيه إحصانٌ للفروج، فيه عفَّة للرجل والمرأة، فيه غضّ الأبصار، فيه مساعدة الفقيرة والقيام عليها، وفيه حمايتها وصيانتها عن الفساد.\nففي النكاح المُتعدد خيرٌ كثيرٌ، ومصالح كبيرة، ولكن كثيرًا من النساء يجهل ذلك، وبعض الأولياء يجهل ذلك، فالواجب التَّنَبُّه لهذا الأمر، فنصف الرجل وربع الرجل وثلث الرجل خيرٌ من بقائها وحدها، ثم الرجل يدخل عليها، ويصونها، ويُهاب، ويُنْفِق عليها إذا كانت فقيرةً.\nوعلى كل حالٍ، المصلحة عظيمة في التَّعدد، وهكذا كل ما شرع الله فيه مصلحة عظيمة، وإن جهل الناس ذلك، والله ما شرع التَّعدد إلا لمصلحةٍ.\nوكان فيمَن قبلنا يُباح للرجل أن يجمع تسعين ومئة، كان عند سليمان بن داود تسعون امرأةً عليه الصلاة والسلام، تسعون، وكان عند أبيه داود مئة امرأةٍ، ثم منع الله في شريعة محمدٍ ما زاد عن أربعٍ، خفف على هذه الأمة، وجعلها أربعًا فقط، ولكن النِّساء ما يعقلن هذا الأمر، وبعض الأولياء كذلك ما يعقلن المصلحة، ولهذا فكثيرٌ منهن يكره التَّعدد، ويأبى من التَّعدد، ويمتنع من التزوج بمَن عنده امرأة.\nوبعض دُعاة الباطل في بعض الإذاعات والصَّحافة أو غير ذلك يفعلون ما يُنَفِّر المرأةَ من الزوج الذي عنده امرأة، كأنَّها جريمة، هذا منكرٌ -نعوذ بالله منه- وهؤلاء الذين يُنَفِّرون من ذلك جهلة بأمر الله، أو فُسَّاق عُصاة لله -نسأل الله العافية.\nفيجب التَّنَبُّه لهذا الأمر، والواجب على المؤمن أن يرضى بما شرع الله، يقول الله سبحانه: ذَلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنْزَلَ اللَّهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:9]، الواجب على المؤمن والمؤمنة الرضا بما شرع الله، ومحبته، وعدم كراهته ولو على نفسه.","link":"https://binbaz.org.sa/fatwas/4318/ما-المنافع-التي-تحصل-بتعدد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0363.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":448,"question":"الزوجة إذا اشترط على زوجها لو تزوج عليها فهي طالق، هل هو وجيه أو هو شرط مخالف للشرع؟","title":"حكم اشتراط الزوجة عدم الزواج عليها","answer":"الجواب: لها الخيار إذا اشترطت، المسلمون على شروطهم، الشرط ينفعها والزواج يضرها، وصرح العلماء أن لها شرطها  وأن لها الخيار؛ إن شاءت سمحت وإن شاءت فارقته، لا يحتاج طلاق ولا يحتاج شيء.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6171/حكم-اشتراط-الزوجة-عدم-الزواج-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/shart006.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":513,"question":"بعض التربويين يقترحون ألا يتزوج الإنسان إلا بعد سن النضوج 21 أو 25 سنة، فما رأيكم؟","title":"ما الرد على من يرى تأخير سن الزواج؟","answer":"الجواب: هم مشرِّعون ولا عبيد؟! هم عبيد ولا مشرِّعون؟! الطلاب: عبيد. الشيخ: والعبد يعمل بشرع الله ولا يعمل برأيه؟! (......). (دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6343/ما-الرد-على-من-يرى-تاخير-سن-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/maram078 - 01 -  Start.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":528,"question":"النساء في الخارج لا يكون لهن ولي؟","title":"من يكون ولي الزواج للنساء في الخارج؟","answer":"الجواب: وليهن القضاء إن كان في دولة مسلمة، وإذا كان ما في دولة مسلمة فرئيس المركز الإسلامي يقوم مقام القاضي، أو رئيس الجمعية الإسلامية؛ حتى لا تتعطل.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6359/من-يكون-ولي-الزواج-للنساء-في-الخارج","audio":"https://files.zadapps.info/binbaz.org.sa/maram094 - 04 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":529,"question":"بالنسبة للصغيرة لو أُجبرت على الزواج؟","title":"ما حكم إجبار الصغيرة على الزواج؟","answer":"الجواب: إذا كانت بكرًا لا تُجبر، أما الصغيرة اللي دون التسع مثل ما تزوج النبي ﷺ عائشة زوَّجه إياها الصديق .\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6360/ما-حكم-اجبار-الصغيرة-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/maram095 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":530,"question":"هل للشهود سماع إذن الزوجة البكر؟","title":"هل للشهود سماع إذن الزوجة البكر؟","answer":"الجواب: نعم، إذنها السكوت، إذا استأذنها أبوها وسكتت يكفي؛ هو مُصَدَّق.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6361/هل-للشهود-سماع-اذن-الزوجة-البكر","audio":"https://files.zadapps.info/binbaz.org.sa/maram096 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":532,"question":"إذا لم تُستأذن البكر هل يبطل زواجها؟","title":"حكم زواج البكر بدون إذنها","answer":"الجواب: ج: نعم، ما يصح زواجها.","link":"https://binbaz.org.sa/fatwas/6363/حكم-زواج-البكر-بدون-اذنها","audio":"https://files.zadapps.info/binbaz.org.sa/maram098 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":533,"question":"البلاد الذين يحكمون بالمذهب الحنفي: إذا زوجوا بغير ولي ثم جاءت المرأة واستفت على مذهب آخر ماذا يكون؟","title":"ما حكم الزواج بغير ولي؟","answer":"الجواب: هذا محل نظر، قد يكون حكم لها حاكم، فهو محل نظر، فعلى جمهور أهل العلم لا بدّ من ولي، ومذهب الأحناف هذا مذهب ضعيف لا يُعَوَّل عليه.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6364/ما-حكم-الزواج-بغير-ولي","audio":"https://files.zadapps.info/binbaz.org.sa/maram099 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":535,"question":"اليتيمة هل تجبر؟","title":"حكم إجبار اليتيمة على الزواج","answer":"الجواب: لا،ـ يستأذنها أخوها أو عمها.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6366/حكم-اجبار-اليتيمة-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/maram101 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":536,"question":"اشتراط العدالة في الولي؟","title":"هل تُشترط العَدَالة في ولي النكاح؟","answer":"الجواب: هذا هو المشروع عند العلماء؛ لا بدّ من العدالة. والقول بأنه لا يشترط قول قوي؛ لأن الرسول ﷺ أطلق لا نكاح إلا بولي ولا يعرف أنه استفصل، فإذا كان ما هو كافر؛ فالأمر واسع إن شاء الله ولو كان فيه بعض المعاصي.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6367/هل-تشترط-العدالة-في-ولي-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/maram102 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":537,"question":"البكر التي عُقِد عليها ولم يُدْخَل بها يبقى عليها حكم البِكْر في الاستئذان؟","title":"هل تُستأذن المطلقة التي لم يُدخل بها للزواج؟","answer":"الجواب: ظاهر الحديث أنه يبقى؛ لأنه يقول: \"الثيب\" والثيب هي التي وُطئت، تزوجت ووُطئت. أما إذا ما وُطئت فهي ما زالت بِكرًا، لكن مقتضى العلة أنه لا بدّ من نطقها؛ لأنها زال عنها في الغالب الحياء بعد ما تزوجت، لكن مقتضى التعبير بالبِكر يقتضي أنه يكفي سكوتُها.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6368/هل-تستاذن-المطلقة-التي-لم-يدخل-بها-للزواج","audio":"https://files.zadapps.info/binbaz.org.sa/maram103 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":539,"question":"أيُّما امرأةٍ زوَّجها وليانِ فهي للأول منهما هل يُستفاد من هذا الحديث أن المرأة تُزَوَّج بدون علمها؟","title":"ما حكم تزويج المرأة بدون علمها؟","answer":"الجواب: لا، قد تكون أذنت لهما جميعًا، قد تقول لكل واحد: اللي تشوفه.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6370/ما-حكم-تزويج-المراة-بدون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/maram105 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":545,"question":"لو اشترط الزوج عدم الأولاد؛ ألزم المرأة عند العقد بأكل الموانع؟","title":"هل يجوز اشتراط الزوج عدم الإنجاب؟","answer":"الجواب: يحتاج لتأمل، والله أعلم.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6376/هل-يجوز-اشتراط-الزوج-عدم-الانجاب","audio":"https://files.zadapps.info/binbaz.org.sa/maram111 - 04 - .mp3","categories":["الشروط والعيوب في النكاح"]},{"id":561,"question":"إذا اشترط الولي على الزوج عدم الضرب هل له ذلك؟","title":"حكم اشتراط الولي على الزوج عدم الضرب","answer":"الجواب: له ذلك، لكن في غير ما أباح الله، من باب التأكيد؛ لعله يحذر، وإلا ما أباح الله ليس لأحد الاعتراض عليه.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6392/حكم-اشتراط-الولي-على-الزوج-عدم-الضرب","audio":"https://files.zadapps.info/binbaz.org.sa/maram127 - 02 - .mp3","categories":["الشروط والعيوب في النكاح"]},{"id":694,"question":"ما قولكم في امرأة زُوِّجت قبل بلوغها، وبعد بلوغها رفضت قبول هذا الزواج. هل يجوز لها أن تتزوج بدون طلاق الزوج، أم لابد من الطلاق؟ وما هو الدليل في هذه المسألة إن كان معلومًا؟","title":"هل لمن زُوِّجت صغيرةً الطلاق بعد بلوغها؟","answer":"الجواب: إذا كانت المرأة قد زُوِّجت بإذنها، فعليها السمع والطاعة للزوج، وتنفيذ مقتضى النكاح، وليس لها أن تتزوج سوى زوجها الذي تم له العقد عليها قبل بلوغها، والمزوج لها أبوها؛ لقول النبي ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، قالوا: يا رسول الله كيف إذنها، قال: أن تسكت[1] متفق على صحته، وهو يعم البالغة ومن دونها.\nوفي صحيح مسلم عن ابن عباس رضي الله عنهما أن النبي ﷺ قال: الأيم أحق بنفسها من وليها، والبكر تستأمر، وإذنها سكوتها[2] وخرجه أبو داود والنسائي بإسناد جيد بلفظ: ليس للولي مع الثيب أمر، واليتيمة تستأمر، وصمتها إقرارها[3]، وهذا صريح في صحة نكاح غير البالغة إذا أذنت، ولو بالسكوت.\nأما إذا كانت لم تستأذن والمزوج لها غير أبيها، فالنكاح فاسد في أصح قولي العلماء لكن ليس لها أن تتزوج إلا بعد تطليقه لها، أو فسخ نكاحها منه بواسطة الحاكم الشرعي؛ خروجًا من خلاف من قال: إن النكاح صحيح، ولها الخيار بعد البلوغ، وحسمًا لتعلقه بها، وليس لها أيضًا نكاح غيره حتى تستبرأ بحيضة إن كان قد وطئها.\nأما إذا كان المزوج لها بدون إذنها هو أبوها، فهذه المسألة فيها خلاف أيضًا بين العلماء، فكثير منهم يصحح هذا النكاح إذا كانت البنت بكرًا؛ لمفهوم قوله ﷺ: واليتيمة تستأمر، قالوا: فهذا يدل على أن غير اليتيمة لا تستأمر، بل يستقل أبوها بتزويجها بدون إذنها.\nوذهب جمع من أهل العلم: إلى أن الأب ليس له إجبار ابنته البكر، ولا تزويجها بدون إذنها، إذا كانت قد بلغت تسع سنين. كما أنه ليس له إجبار الثيب، ولا تزويجها بغير إذنها؛ للحديث السابق وهو قوله ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن[4]\nوهو يعم اليتيمة وغيرها، وهو أصح من الحديث الذي احتجوا به على عدم استئذان غير اليتيمة، وهو منطوق، وحديث اليتيمة مفهوم، والمنطوق مقدم على المفهوم؛ ولأنه عليه الصلاة والسلام صرح في رواية ثابتة عنه ﷺ بقوله: والبكر يستأذنها أبوها[5]، وهذا اللفظ لا يبقي شبهة في الموضوع؛ ولأن ذلك هو الموافق لسائر ما ورد في الباب من الأحاديث، وهو الموافق للقواعد الشرعية في الاحتياط للفروج، وعدم التساهل بشأنها.\nوهذا القول هو الصواب؛ لوضوح أدلته، وعلى هذا القول يجب على الزوج الذي عقد له والد البكر عليها بدون إذنها، أن يطلقها طلقة واحدة؛ خروجًا من خلاف العلماء، وحسمًا لتعلقه بها بسبب الخلاف المذكور.\nوهذه الطلقة تكون بائنة ليس فيها رجعة؛ لأن المقصود منها قطع تعلق المعقود له بها، والتفريق بينه وبينها، ولا يتم ذلك إلا باعتبارها طلقة مبينة لها بينونة صغرى؛ كالطلاق على عوض.\nويجب أن يكون ذلك بواسطة قاضٍ شرعي يحكم بينهما، ويريح كل واحد منهما من صاحبه على مقتضى الأدلة الشرعية؛ لأن حكم القاضي يرفع الخلاف في المسائل الخلافية، ويحسم النزاع. أما إذا كانت البنت دون التسع فقد حكى ابن المنذر: إجماع العلماء على أن لأبيها تزويجها بالكفء بغير إذنها؛ لأن الرسول ﷺ تزوج عائشة رضي الله عنه بدون إذنها وعلمها، وكانت دون التسع.\nونسأل الله أن يوفقنا وإياكم وسائر المسلمين للفقه في دينه والثبات عليه؛ إنه خير مسؤول، والسلام عليكم[6].","link":"https://binbaz.org.sa/fatwas/19445/هل-لمن-زوجت-صغيرة-الطلاق-بعد-بلوغها","audio":"undefined","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":747,"question":"إنَّ كثيرًا من الخُطَّاب أتوا إليَّ يخطبوا والدتي، وأنا أكره في نفسي أن أُزوّجها وأنا موجود، وأكره أن يدخل عليها رجلٌ غير أبي، فهل تصرُّفي هذا خطأ أم هو صواب؟","title":"هل يجوز منعُ الابن أمه من الزواج؟","answer":"الجواب: بل هو خطأ منك، إذا كانت ترغب الزواج هي فالواجب عليك تزويجها، ولا حرج في ذلك عليك، بل الواجب أن تسعى في برِّها، كما تسعى في برِّ والدك، وحقّ الأم أكبر وأعظم من حقِّ الأب، يقول النبيُّ ﷺ لما سُئل: قال له رجلٌ: يا رسول الله، مَن أحقُّ الناس بحُسن صُحبتي؟ قال: أمُّك، قال: ثم مَن؟ قال: أمك، قال: ثم مَن؟ قال: أمك، قال: ثم مَن؟ قال: أبوك، هو في الرابعة، فحق الوالدة أكبر.\nفإذا كانت ترغب في الزواج؛ فعليك أن تُجيبها إلى ذلك إذا خطبها الشخصُ المناسبُ، وليس لك أن تُعرقل الموضوع من أجل هواك، لا.","link":"https://binbaz.org.sa/fatwas/20648/هل-يجوز-منع-الابن-امه-من-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0570حكم منع الآم من الزواج ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":951,"question":"هل يجوز للمرأة أن تشترط على زوجها في وثيقة عقد القران: ألا يتزوج عليها بزوجةٍ أخرى؟","title":"هل يجوز للمرأة اشتراط عدم الزواج بأخرى؟","answer":"الجواب: لها أن تشترط، ذكر جمعٌ من العلماء أنَّ لها أن تشترط ألا يتزوج عليها، فإذا تزوج عليها فلها الخيار: إن شاءت بقيت، وإن شاءت فسخت النكاح، فالمسلمون على شروطهم، فلها أن تشترط عليه أن يُبقيها في بيتها، أو بيت أهلها، أو في بلدٍ معينٍ لا ينقلها منه، فالمسلمون على شروطهم.","link":"https://binbaz.org.sa/fatwas/20986/هل-يجوز-للمراة-اشتراط-عدم-الزواج-باخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0781هل يجوز للمرأة أن تشترط على زوجها في وثيقة عقد القِران الاَّ يتزوج عليها يزوجة أخرى؟ ابن باز.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":1594,"question":"الراجح في الكفاءة المُعتبرة في النكاح: في الدِّين فقط؟","title":"ما الكفاءة المُعتبرة في النكاح؟","answer":"الجواب: الدِّين والحرية.","link":"https://binbaz.org.sa/fatwas/21698/ما-الكفاءة-المعتبرة-في-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الكفاءة المُعتبرة في النكاح.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":1632,"question":"هذا رجل سكران، تقول امرأتُه: هل يجب عليَّ أن أطلب منه الطلاق أم أصبر عليه مع صلاته، فهو يُصلِّي؟","title":"هل يجوز للمرأة البقاءُ عند زوج سِكِّير؟","answer":"الجواب:\nلا، ما هو بواجب، لكن إن طلبتْ فلها عذر، وعليها أن تنصحه وتجتهد في نصحه، لعل الله يهديه بسببها، وإن طلبت الطلاقَ فلها عذر.\nس: لكن يجوز لها أن تبقى معه؟\nج: تبقى، فليس بكافرٍ.","link":"https://binbaz.org.sa/fatwas/21737/هل-يجوز-للمراة-البقاء-عند-زوج-سكير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للمرأة البقاء عند زوج سكران.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":2044,"question":"هل يجوز للابن أن يتزوج أخت زوجة أبيه؟","title":"حكم زواج الرجل بأخت زوجة أبيه","answer":"الجواب:\nزوجة أبيه ما هي بأمه.\nس: لا.\nالشيخ: ما في بأس، واحد يتزوج هذه وواحد يتزوج هذه، ما في بأس ما داموا أخوات ما يخالف.","link":"https://binbaz.org.sa/fatwas/22161/حكم-زواج-الرجل-باخت-زوجة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للابن أن يتزوج أخت زوجة أبيه.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":2127,"question":"السفر بنية الزواج بالطلاق ما حكمه؟","title":"حكم السفر من أجل الزواج بنية الطلاق","answer":"الجواب:\nلا حرج عند الجمهور، لكن تركه أحوط وأفضل؛ خروجًا من خلاف مَن حرَّمه.","link":"https://binbaz.org.sa/fatwas/22245/حكم-السفر-من-اجل-الزواج-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السفر بنية الزواج بالطلاق.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":2608,"question":"اشتراط الكفاءة في النسب في النكاح عليه دليل؟","title":"حكم اشتراط الكفاءة في النسب في النكاح","answer":"الجواب: لا ما عليه، إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] المُعَوَّل عليه التقوى، فاظفر بذات الدين ترتبت يداك.\nس: بالنسبة لحكم زواج القبيلي من خضيري، وكذلك...؟\nالشيخ: ما في بأس، كله ما في بأس، هذه أعراف بين الناس، فاطمة بنت قيس تزوجت بأسامة بن زيد، وهو عتيق وهي من قريش، وعائشة بنت الحسين بن علي بن طالب تزوجت بمصعب بن الزبير، ومصعب ما هو من بطن بني هاشم وهو من عامة قريش.","link":"https://binbaz.org.sa/fatwas/22743/حكم-اشتراط-الكفاءة-في-النسب-في-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدليل على اشتراط الكفاءة في النسب في النكاح.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":2920,"question":"تزوجت ابنة عمي ووَلِيَ عقدَها أبوها، وخالها وأخوها هم الشهود، والبنت راضية وبأطيب حال ولله الحمد، ولكنهم ما شاوروها قبل العقد في الرضا؟","title":"هل يصح عقدُ مَن لم تصرِّح برضاها؟","answer":"الجواب: لا، إن أدخلت عليك وهي راضية فهي راضية.\nس: نعم؟\nالشيخ: لما أدخلت عليك وسكتت فمعناه راضية.\nس: معناه العقد صحيح؟\nالشيخ: ما فيه شيء أبدًا، خل عنك وساوس الشيطان.","link":"https://binbaz.org.sa/fatwas/23076/هل-يصح-عقد-من-لم-تصرح-برضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة عقد من لم تصرح برضاها.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3052,"question":"الكفاءة بين الزوجين من حيث النَّسَب هل تُشترط؟","title":"هل تُشترط الكفاءة بين الزوجين في النَّسَب؟","answer":"الجواب: ما هو بشرط، لا، في الدين إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] في الدين، لا يتزوج المسلم الكافرة؛ لأن الله يقول: وَلَا تَنْكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221]، وَلَا تُنْكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا [البقرة:221]،  لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] وكذلك الحرية والعبودية فيها تفصيل.\nس: الذي يقول: خضيري؟\nالشيخ: هذا شيء جديد بين العامة، وإلا الأصل عرب وعجم، هذا الأصل، وبعضهم لبعض أكفاء إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13].\nس: بعضهم يستدل بقول عمر: لأمنعن ذوات الأنساب؟\nالشيخ: إن صح فهذا محل اجتهاده .","link":"https://binbaz.org.sa/fatwas/23212/هل-تشترط-الكفاءة-بين-الزوجين-في-النسب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تشترط الكفاءة بين الزوجين من حيث النسب.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3483,"question":"بعض العامة يتشددون في نهي تشبيك الأصابع في أثناء عقد النكاح؟","title":"حكم تشبيك الأصابع في أثناء عقد النكاح","answer":"الجواب: لا ما له أصل هذا، هذا سوء ظن.","link":"https://binbaz.org.sa/fatwas/23660/حكم-تشبيك-الاصابع-في-اثناء-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تشبيك الأصابع في أثناء عقد النكاح.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3644,"question":"إذا تزوج المرأة بدون ولي هل يبطل النكاح؟","title":"هل يبطل زواج المرأة بدون ولي؟","answer":"الجواب: إذا كان يوجد ولي فنعم، ولم يستأذن ولم يوكل؛ يبطل النكاح لا نكاح إلا بولي.","link":"https://binbaz.org.sa/fatwas/23832/هل-يبطل-زواج-المراة-بدون-ولي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم زواج المرأة بدون ولي.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3645,"question":"إذا كان وليها كافرًا أسلمت ...؟","title":"حكم تزويج مَنْ كان وليها كافرًا","answer":"الجواب: الكافر ما له ولاية، ولكن إن كان ولا بدّ وهي ما لها ولي، كونه يتولاه حتى لا تقع فتنة؛ أنسب، يتولاه وهي تزوّج نفسها في الحقيقة، لكن كونها تشاوره حتى لا يقع فتنة بينه وبين الزوج وحتى لا يقع شر بينهم للضرورة، وإلا ليس وليًّا شرعيًّا.","link":"https://binbaz.org.sa/fatwas/23833/حكم-تزويج-من-كان-وليها-كافرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم في من كان وليها كافرًا.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3646,"question":"لو ولي الزوجة عاصٍ؟","title":"هل تزوّج نفسها مَنْ كان وليها عاصيًا؟","answer":"الجواب: ولو، الصواب يزوّجها ولو كان غير عدل، لا تزوج نفسها، لكن إذا وجد الولي العدل فهو أوْلى من غيره، والصواب أنها لا تُشترط العدالة في الولي؛ لأن الغيرة موجودة، يزوجها وليها؛ أبوها أو الأقرب فالأقرب، وإن كان فيه نقص في العدالة، ولا تزوّج نفسها.\nس: وإن كانت بدعته شركية؟\nالشيخ: لا، الكافر ما له ولاية.","link":"https://binbaz.org.sa/fatwas/23834/هل-تزوج-نفسها-من-كان-وليها-عاصيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم في من كان وليها عاصٍ أو مبتدع.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3647,"question":"رضا المرأة شرط لصحة العقد؟","title":"هل رضا المرأة شرط لصحة الزواج؟","answer":"الجواب: لا بدّ منه، نعم، إذا كنت بنت تسع فأكثر، أما دون التسع فلأبيها أن يزوجها، إذا كانت دون التسع كما زوج أبو بكر عائشة على النبي ﷺ وهي دون التسع ولم يستأذنها؛ لأنها لا رأي لها ما دام دون التسع، لأبيها خاصة أن يزوّجها دون التسع. أما غير الأب فلا يزوّج إلا بإذن، بعدما تكون بنت تسع فأكثر، وإذن الصغيرة سكوتها، البكر إذنُها سكوتُها.","link":"https://binbaz.org.sa/fatwas/23835/هل-رضا-المراة-شرط-لصحة-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل رضا المرأة شرط لصحة العقد.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3648,"question":"سمعنا في بعض كتب الفقه أن الأب يُرْغِم - إن رأى فيه مصلحة-  ابنه أو بنته على الزواج؟","title":"هل للولي إرغام ابنه أو ابنته على الزواج؟","answer":"الجواب: ليس بصواب، لا يُجْبَر الولد ولا البنت عليه. أما إذا كان صغيرًا دون التسع؛ له أن يزوجه وله أن يزوجها إن كانت صغيرة وهو صغير دون التسع، الأب خاصة.","link":"https://binbaz.org.sa/fatwas/23836/هل-للولي-ارغام-ابنه-او-ابنته-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُرغم الولي ابنه أو ابنته على الزواج.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3649,"question":"إذا كان الولي يرى أن في هذا الزواج مفسدة شرعية هل له أن يمنعها من هذا الزوج؟","title":"هل للولي منع زواج المرأة لمفسدة شرعية؟","answer":"الجواب: يجتهد في هذا ولا يزوّجها إلا على وجه فيه خير لها ومصلحة لها، وإذا تنازعوا يرجعوا إلى المحكمة، لكن هو عليه أن يجتهد؛ لا يزوّجها إلا بالرجل الصالح الذي يراه أهلًا لها.","link":"https://binbaz.org.sa/fatwas/23837/هل-للولي-منع-زواج-المراة-لمفسدة-شرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمنع الولي المرأة من الزواج إذا كان يرى أن في هذا الزواج مفسدة شرعية.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3650,"question":"إذا كان الولي هو الخاطب يتولى طرفي العقد؟","title":"كيف يتم الزواج إذا كان الولي هو الخاطب؟","answer":"الجواب: نعم، وفيه النهي عن ظلم اليتامى، وأنه لا يجوز ظلم اليتيمات، بل يجب على وليهن تزويجهن، بعض الناس قد يظلمها لأجل مالها، لعلها تموت فيرثها فيتأخر عن تزويجها، وهذا من الظلم، بل يجب أن يزوجها متى خطبها الكفء، وليس له أن يحبسها، فإن رغب فيها ورغبت فيه فلا بأس أن يتزوجها ويتولى طرفي العقد.","link":"https://binbaz.org.sa/fatwas/23838/كيف-يتم-الزواج-اذا-كان-الولي-هو-الخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا كان الولي هو الخاطب يتولى طرفي العقد.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3651,"question":"إذا لم يكن لها ولي أصلًا ولا حاكم؟","title":"حكم زواج من ليس لها ولي ولا حاكم؟","answer":"الجواب: تزوّج نفسها، وإن تيسر يزوجها مثل رئيس المركز الإسلامي أو شبهه أنسب؛ لأنه يقوم مقام السلطان، مثل ما قد يقع في أمريكا وأشباهها، رؤساء المراكز الإسلامية مناسب إذا قالت له والتمس لها الكفء، فإذا لم يتيسر تزوّج نفسها للضرورة بحضرة شاهدين..... زوجتك نفسي أو قد تزوجتك بكذا، بحضرة شاهدين وبمهر، تزوج نفسها، يتولى طرفا العقد: زوجتك نفسي، وقبلتُ.\nس: لو وجد مسلم ولو لم يكن سلطانًا هل لها أن توكله؟\nالشيخ: لا يجب عليها؛ لأنه ليس وليًا لها، لكن إن وكلته فلا بأس.","link":"https://binbaz.org.sa/fatwas/23839/حكم-زواج-من-ليس-لها-ولي-ولا-حاكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زواج من لم يكن لها ولي أصلا ولا حاكم.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3654,"question":"إذا أخبرها (الثيب) وسكتت؟","title":"هل يصح سكوت غير البكر للإذن بالنكاح؟","answer":"الجواب: لا يكفي لا بدّ من إذنها الصريح إلا البكر، البكر تستحي فيكفي سكوتها، أما الثيب فلا بدّ من أمرها.\nس: إذا رضيت بعد العقد هل يجدد؟\nالشيخ: يجدد نعم.\nس: إذا دخل بها وهي كارهة..؟\nالشيخ: يُفسخ النكاح، وإذا رضيت بعدين يجدد، إذا رضيت بعد ذلك.\nس: ويكون صداق آخر أو يُكتفى بالصداق الأول؟\nالشيخ: الصداق الأول بما استحل من فرجها، لكن لا بدّ من صداق ثانٍ ولو قليل.\nس: ما جاء في بعض الألفاظ \"قد أجزت ما فعل أبي\"؟\nالشيخ: جاء في بعض الروايات: خيّرها النبيﷺ، لكن الأصح الرد؛ لأن النكاح وقع باطلًا.","link":"https://binbaz.org.sa/fatwas/23842/هل-يصح-سكوت-غير-البكر-للاذن-بالنكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإذن في النكاح لا بد أن يكون صريحا إلا البكر.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3655,"question":"الإيجاب والقبول يكون في مجلس واحد أو يتراخى؟","title":"هل يجوز تأخر قبول الزواج عن الإيجاب؟","answer":"الجواب: في مجلس واحد.\nس: لو تراخى صح؟\nالشيخ: قريب في مجلس واحد، قريب شيء يسير، مثل ما جرى مع صاحب الخاتم تراخى قليلًا.","link":"https://binbaz.org.sa/fatwas/23843/هل-يجوز-تاخر-قبول-الزواج-عن-الايجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإيجاب والقبول في النكاح على الفور أو على التراخي.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3666,"question":"هل لها أن تشترط عليه أن يكون الطلاق إليها؟","title":"هل للمرأة اشتراط جعل الطلاق بيدها؟","answer":"الجواب: لا، الطلاق ما هو لها، الطلاق للرجال.","link":"https://binbaz.org.sa/fatwas/23854/هل-للمراة-اشتراط-جعل-الطلاق-بيدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للمرأة أن تشترط الطلاق على زوجها.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":3667,"question":"إذا لم تشترط عليه أن يُبقيها عند أهلها فهل له أن يذهب بها حيث يكون عمله؟","title":"حكم اشتراط المرأة على زوجها","answer":"الجواب: هو أولى بها، يسكنها حيث يشاء ما يسكن مثلها، إنما تكون عند أهلها إذا شرطت.\nس: إذا شرطت أن زواجه عليها يكون طلاقاً لها، وهل تطلق بمجرد الزواج؟\nالشيخ: لها شرطها، المسلمون على شروطهم؛ لأن الزواج عليها يضرها.\nس: إذا شرط عليها أن يأتيها في الأسبوع مرة؟\nالشيخ: ما عندها ضرة؟\nس: عندها.\nالشيخ: ما يجوز لا بدّ من عدل.","link":"https://binbaz.org.sa/fatwas/23855/حكم-اشتراط-المراة-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اشتراط المرأة على زوجها.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":3840,"question":"إذا كان الزوج الثاني عِنِّينًا؟","title":"هل تَحِلُّ لزوجها الأول إذا كان الثاني عِنِّينًا؟","answer":"الجواب: لا تحل للأول حتى يطأها الثاني أو يطلقها ويتزوجها الآخر. المقصود حَتَّىٰ تَنكِحَ زَوْجًا آخر، كما قال الله، نكاحًا فيه جماع.","link":"https://binbaz.org.sa/fatwas/24043/هل-تحل-لزوجها-الاول-اذا-كان-الثاني-عنينا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا كان الزوج الثاني عنينًا، فهل تحل للأول.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":5072,"question":"رجلٌ تزوَّج من امرأةٍ فعل بها الفاحشة قبل الزواج، ولم يكن ذلك برغبته، بل مُرغمًا؛ وذلك لدخول الشيطان بينهما، وخوفًا من الفضيحة والعار تزوج منها، وأنجبت منه أطفالًا، ولكن الإثم حاك في نفسه، وكره أن يطَّلع عليه الناس فعلًا، وشكوكه دائمًا بها هو ما يجعله فعلًا يرى الماضي دائمًا بين عينيه، ويجعله يشك فيها، وكأنما أعطته قبل الزواج ستُعطيه لغيره بعد زواجه منها، فطلَّقها، وأحسَّ بالراحة النَّفسية فعلًا بعد ذلك، فهل عليه إثمٌ في ذلك؟ وما حال أبنائه في مثل هذه الحالة؟ وهل في ذلك شيءٌ من الناحية الدينية؟ وهل لها الحقُّ في تربية أبنائه أو ردّهم؛ نظرًا لكونها هي التي حاولت إغراءه في بداية الأمر قبل الزواج، واستدرجته لفعل الفاحشة، وربما لا تكون تربيتها إسلاميةً؟  علمًا بأن زواجه منها في بادئ الأمر -وهو ما ذُكِرَ بعاليه- خوفًا من عقاب الله ، علمًا بأنها ثيب عندما تزوَّجها. جزاكم الله خير الجزاء.","title":"حكم من تزوج مَن زَنا بها للسّتر ثم شك بحالها فطلقها","answer":"الجواب: إذا كان الزواجُ بها عن توبةٍ فلا بأس بذلك، إذا كانت أظهرت التوبة والندم، وهو كذلك؛ فلا بأس أن يتزوجها للستر والتَّغطية على ما وقع، ومَن ستر مسلمًا ستره الله في الدنيا والآخرة.\nوأما إن كان تزوجها من أجل مجرد الستر فقط، أو لأجل تشديد أبيه أو أمه أو غير ذلك، وهي على حالها ما أظهرت توبةً؛ فلا يجوز هذا النكاح، ولا يصحّ، وعليه التوبة من ذلك، عليك التوبة من ذلك، وقد أحسنت في طلاقها إذا كان ظاهرها عدم الاستقامة، وأولادك لاحقون بك لأجل شُبهة النكاح، أولادك لاحقون بك من أجل شبهة النكاح، وإن كان نكاحًا فاسدًا، إذا كانت ما تابت من فعلها القبيح، وقد أحسنتَ كما تقدم في الطلاق إذا كانت حالها سيئةً.\nأما إن كانت قد تابت وأظهرت النَّدم وأنت كذلك، وفعلتما ذلك تستُّرًا وإبعادًا للشر؛ فأنتم على خيرٍ إن شاء الله، ولا حرج عليكم. \nلكن ما دامت لم تظهر منها التوبة، وتخشى منها أن تفعل مع غيرك ما فعلتْ معك ولهذا طلَّقتها؛ فقد أحسنتَ في ذلك، والأولاد أولادك، وأما كونهم يبقون عندها أو يُنقلون إليك فهذا عند المحاكم، ما هو عندنا، لكن إذا اصطلحتم فيما بينكم -مع أبيها ومع أقاربها- على أنهم يكونون عندك خوفًا على أولادك؛ هذا لا بأس به، وإن كانت قد استقامت وحسنت حالها فلا بأس ببقاء الأولاد عندها، إذا كانت قد حسنت حالها، ولكن أنت بسبب الشك وبسبب الوسواس طلَّقتها، فلا بأس ببقاء الأولاد عندها؛ لكونها تحسنت حالها.\nأما إن كنت تُسيء الظنَّ بها، ولا ترى أنَّ حالها تحسنت؛ فتعمل ما تستطيع من الطرق الشرعية مع المحكمة في نقل أولادك إليك، أو بواسطة الأخيار، يُصلحون بينكم؛ حتى تسمح هي وأهلها بإعطائك أولادك، فإن لم يتيسر ذلك فالمحكمة، من دون أن تُبين أمر الزنا، ولكن تطلب أولادك وتقول: إنك تخشى عليهم.","link":"https://binbaz.org.sa/fatwas/29384/حكم-من-تزوج-من-زنا-بها-للستر-ثم-شك-بحالها-فطلقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من تزوج من زنا بها للسّتر ثم شك بحالها.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":5098,"question":"يقول هذا السائل بعد السلام على فضيلتكم:رجل مسافر إلى الخارج في مهمة تتعلق بالدراسة، وكان ملزمًا بذلك، وهو لم يتزوج بعد، ويخشى على نفسه، فهل له الزواج من هناك، مضمرًا في نفسه أنه سيطلقها عندما يسافر إلى بلده، دون أن يعلمهم بذلك؟","title":"حكم الزواج بنية أنه سيطلقها عندما يسافر","answer":"الجواب: لا حرج في ذلك إذا تزوج في محل السفر وفي نيته أنه يطلق إذا أراد الرجوع، لا حرج عند جمهور أهل العلم. بعض أهل العلم قد توقف في هذا، وخشي أن يكون من باب نكاح المتعة، وليس كذلك، المتعة يشترط فيها مدة معلومة، يتزوج على أنه يطلقها بعد شهر أو شهرين، على أنه لا نكاح بينهما بعد شهر أو شهرين أو ثلاثة، هذا نكاح المتعة. أما الزواج المطلق ليس فيه شرط، ولكن في نفسه ونيته أنه يطلقها عند سفره من البلاد، هذا لا يكون متعة، فقد يطلقها وقد يرغب فيها، فليس هذا من باب المتعة على الصحيح، وعلى ذلك جمهور أهل العلم. والله أعلم، وصلَّى الله وسلَّم على نبينا محمد، وعلى آله وصحبه أجمعين.","link":"https://binbaz.org.sa/fatwas/30006/حكم-الزواج-بنية-انه-سيطلقها-عندما-يسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 23.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":5310,"question":"هل يجوز أن تكون العِصمة في يد المرأة إذا اشترطت ذلك ووافقها الرجل عليه، وما الدليل؟","title":"هل يجوز أن تكون العِصمة في يد المرأة؟","answer":"الجواب: في أول العَقد لا، العِصمة بيد الرجال، قوامون على النساء، أما بعد ذلك إنْ علَّق الطلاق على فعلها أو على اختيارها؛ فلا بأس. الدليل: قول النبي ﷺ: المسلمون على شروطهم، وقوله ﷺ: إن أحق الشروط أن يوفّى به ما استحللتم به الفروج. لكن الطلاق بيد... الزوج، فإذا وكّلها بطلاق نفسها أو علَّق الطلاق على فعلها: إنْ خرجتِ أو إنْ كلمت فلانًا، وقَّت، إذا أراد الطلاق.[1]","link":"https://binbaz.org.sa/fatwas/30967/هل-يجوز-ان-تكون-العصمة-في-يد-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 030.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":5346,"question":"ما قولكم فيمَن لا يُزوج ابنته لحجَّامٍ أو جزَّارٍ أو حدَّادٍ، حتى ولو كان رجلًا مُتدينًا ذا خلقٍ، فهل هذا العمل صحيح بالنسبة لعيب الزواج من جزارٍ أو حجَّامٍ؟","title":"حكم مَن لا يُزوج ابنته لحجَّامٍ أو جزَّارٍ أو حدَّادٍ","answer":"الجواب: يقول الله جلَّ وعلا: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]، فإذا وجد الأتقى زوَّج، سواء كان من العرب أو من العجم، أو من بني هاشم أو غيرهم، قال النبي للأنصار: يا بني بياضة، أنكحوا إلى أبي هندٍ، وأنكحوا إليه، وكان حجَّامًا. فالمقصود أن العبرة بالأعمال الصالحة والتقوى، كونه حجامًا أو حدادًا أو خرَّازًا أو نجارًا أو غير ذلك لا يضرّه، كان داود عليه الصلاة والسلام حدادًا يصنع الدروع ويبيعها وهو نبي الله. فالواجب على المؤمن أن يتحرى لموليته صاحب التقوى، وإذا تيسر من نسبٍ طيبٍ فهذا خيرٌ إلى خيرٍ كما قال ﷺ: تُنكح المرأةُ لأربعٍ: لمالها ولحسبها ولجمالها ولدينها، فاظفر بذات الدين تربت يداك، ويقول النبي ﷺ: إذا خطب إليكم مَن ترضون دينَه وخُلقه فزوِّجوه، ما قال: نسبه، مَن ترضون دينَه وخُلقه فزوِّجوه، إلا تفعلوا تكن فتنة في الأرض وفساد كبير. وقد زوَّج النبي ﷺ فاطمة بنت قيسٍ أسامة بن زيد عتيقه ابنَ عتيقه، وهي من قريش، وزوَّج أبو حذيفة بن عتبة سالمًا مولى أبي حذيفة بنته. المقصود أنَّ المؤمن يتحرّى العمل الطيب والتقوى والخير، ولا يهمه كونه من بني فلانٍ، أو كونه يعمل كذا، أو يعمل كذا، متى كان كفئًا في دينه: إذا خطب إليكم مَن ترضون دينه وخُلقه فزوِّجوه، إلا تفعلوا تكن فتنة في الأرض وفساد كبير، زوَّجه بنت أخيه، زوَّجه أبو حذيفة ابنةَ أخيه، نعم، مولى سالم.[1]","link":"https://binbaz.org.sa/fatwas/31025/حكم-من-لا-يزوج-ابنته-لحجام-او-جزار-او-حداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 067.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":5900,"question":"التي يريدها الرجل أن يشترطوا عليه طلاق الأولى، وهل يجوز له أن يقبل هذا الشرط دون سببًا من الأولى؟","title":"حكم اشتراط الزوجة الثانية طلاق الزوجة الأولى","answer":"الجواب: هذا لا يجوز، وبعض الناس يقولون: إذا خطب منهم آخر، وعند الخاطب زوجة، يقولون: بشرط أن تطلق زوجتك؛ هذا لا يجوز، الرسول ﷺ نهى عن ذلك، نهى أن تشترط المرأة طلاق أختها. فالحاصل: أنه لا يجوز للمخطوب منهم أن يشترطوا على الخاطب أن يطلق زوجته الحالية، بل هذا من ظلمهم، وعدوانهم، فليس لهم هذا الشرط، ولا يلزمه الوفاء لهذا الشرط؛ فإن هذا شرط منكر، فيخبرهم أن هذا لا يجوز، وأن الرسول نهى عن هذا الشرط، ولا يليق منكم ذلك، فإن صمموا، فشرطهم باطل، كما قال النبي ﷺ في قصة بريرة: كل شرط ليس في كتاب الله فهو باطل، وإن كان مائة شرط، قضاء الله أحق، وشرط الله أوثق.","link":"https://binbaz.org.sa/fatwas/1249/حكم-اشتراط-الزوجة-الثانية-طلاق-الزوجة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_245.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6088,"question":"إذا تزوج رجل بنتًا، وبعد الدخول عليها لم يجدها بكرًا، فماذا يفعل؟","title":"حكم من تبين أنها ليست بكراً بعد الدخول بها","answer":"الجواب: هذا له أسباب قد تكون البكارة ذهبت بأسباب غير الزنا، فيجب حسن الظن إذا كان ظاهرها الخير، وظاهرها الاستقامة يجب حسن الظن في ذلك، أو كانت قد فعلت فاحشة، ثم تابت، وندمت، وظهر منها الخير لا يضره ذلك، وقد تكون البكارة زالت بشدة الحيض، فإن الحيضة الشديدة تزيل البكارة كما قال العلماء.  وكذلك تزول البكارة ببعض الوثبات إذا وثبت من مكان إلى مكان، وطمرت من مكان إلى مكان، أو نزلت من محل مرتفع إلى محل سافل بقوة، قد تزول البكارة، فليس من لازم البكارة أن يكون زوالها بالزنى، لا، فإذا ادعت أنها زالت البكارة بأمر غير الفاحشة؛ فلا حرج عليه، أو بأمر من فاحشة، ولكنها مغصوبة مكرهة، فإن هذا لا يضر أيضًا، إذا كان قد مضى عليها حيضة بعد الحادث، أو ذكرت أنها تابت، وندمت، وأن هذا الذي فعلته في حال سفهها، وجهلها، ثم تابت، وندمت؛ فإنه لا يضر، ولا ينبغي أن يشيع ذلك، بل ينبغي أن يستر عليها، فإن غلب على ظنه صدقه، واستقامتها؛ أبقاها، وإلا طلقها مع الستر، وعدم إظهار ما يسبب الفتنة، والشر.  السؤال: ..؟ الجواب: لا، ما يلزم إلا إذا عرف أنها فاحشة؛ لأن البكارة قد تزول بالحيض، وقد تزول بأسباب أخرى، وقد تكون مكرهة، والمكرهة لها حكم من لم يفعل شيئًا، وقد تكون أيضًا... فعلته عن موافقة، ولكن الله تاب عليها، وتحسنت حالها.\n\nالسؤال: بعض البلدان يحبوا أن يروا البكارة في الثوب، فإذا وجد رجل امرأته فيها غير بكارة، وأراد أن يستر ذلك، فكلمها بذلك، وفكها، هل لهم أن يردوا له فلوسه؟ الجواب: هذا إذا كان ضروري يمكن أن يفعل هذا بشيء آخر، بدم آخر للستر عليها، وهو بعد ذلك مخير، إن شاء أبقاها، وإن شاء طلقها، يمكن أن يجعل دمًا من غير البكارة إذا كان ضروريًا؛ لأنه لا بدّ من إظهار شيء في عاداتهم، فإذا لم يفعل اتهموها بالزنى، بإمكانه أن يضع شيئًا من دماء من دم آخر من باب الستر على الناس، والنبي يقول: من ستر مسلمًا؛ ستره الله في الدنيا، والآخرة.","link":"https://binbaz.org.sa/fatwas/1509/حكم-من-تبين-انها-ليست-بكرا-بعد-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_439.mp3","categories":["الشروط والعيوب في النكاح","الآداب والأخلاق"]},{"id":6257,"question":"وآخر يقول: هل الأصل في الزواج واحدة، والتعدد جاء عارضًا لأسباب، أم هو العكس؟","title":"هل الأصل في الزواج التعدد؟","answer":"الجواب: الأصل التعدد، والواحدة هي التي يحصل بها عند العجز؛ لأن الله -جل وعلا- قال: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3] فدل على أن الأصل هو التعدد، يتزوج ثنتين، أو ثلاثًا، أو أربعًا؛ لأن هذا أقرب إلى إعفاف الرجل، وإلى كثرة النسل، فإذا عجز؛ اكتفى بواحدة، إن خاف أن لا يعدل؛ اكتفى بواحدة مع ما تيسر من الإماء.","link":"https://binbaz.org.sa/fatwas/1782/هل-الاصل-في-الزواج-التعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_621.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6266,"question":"وآخر يقول: هل الأصل في الزواج واحدة، والتعدد جاء عارضًا لأسباب، أم هو العكس؟","title":"هل الأصل في الزواج التعدد؟","answer":"الجواب: الأصل التعدد، والواحدة هي التي يحصل بها عند العجز؛ لأن الله -جل وعلا- قال: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3] فدل على أن الأصل هو التعدد، يتزوج ثنتين، أو ثلاثًا، أو أربعًا؛ لأن هذا أقرب إلى إعفاف الرجل، وإلى كثرة النسل، فإذا عجز؛ اكتفى بواحدة، إن خاف أن لا يعدل؛ اكتفى بواحدة مع ما تيسر من الإماء.","link":"https://binbaz.org.sa/fatwas/1782/هل-الاصل-في-الزواج-التعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_621.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6394,"question":"مع توفر الإمكانية، والعدل دون أن يكون هناك مبرر آخر أسمى من مجرد الشهوة؟","title":"حكم الزواج بأكثر من واحدة بنية قضاء الوطر","answer":"الجواب: يجوز أن يكون المبرر لتعدد الزوجات أن يقضي وطره إذا كانت الزوجة لا تعفه الواحدة؛ فلا مانع، بل قد تكون زوجتان أيضاً لا تعفه، والناس أقسام، وطبقات؛ فلا بأس أن يتزوج الثنتين، والثلاث، والأربع إذا دعت الحاجة إلى ذلك، وظن في نفسه العدل، والقيام بما يجب؛ فلا بأس بذلك، والله يقول -جل وعلا-: فَانكِحُواْ مَا طَابَ لَكُم مِّنَ النِّسَاء مَثْنَى وَثُلاَثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلاَّ تَعْدِلُواْ فَوَاحِدَةً [النساء:3]. فلا بدّ أن يتزوج؛ ليجد الزوجة التي يحصل بها قضاء الوطر، والراحة إليها، والسكن إليها مع الزوجة الأولى، ومع الثانية، ومع الثالثة، والرابعة، هي النهاية.","link":"https://binbaz.org.sa/fatwas/1974/حكم-الزواج-باكثر-من-واحدة-بنية-قضاء-الوطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_761.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6403,"question":"خطبت امرأة، وطلب مني شرطً أن لا تخرج من هذه البلاد، كيف يكون ذلك إلا كان عندي منها أولاد فيما بعد، هل تكون في بلد، وأنا في بلد أخرى ؟","title":"حكم اشتراط الزوجة السكن في بلد معين","answer":"الجواب: المسلمون على شروطهم، إذا شرط أولياء المرأة عليه مكانًا معينًا، والتزم به؛ فعليه أن يبقى في البلد حتى يرضوا بمغادرته إياها، فإذا شرطوا عليه أن يكون هو وزوجته في الرياض، أو في المدينة، أو في مكة، أو الطائف، والتزم بذلك، أو في القاهرة، أو في دمشق، أو في أي مكان، والتزم بذلك؛ فعليه أن يوفي بالشرط، إلا بوجود أمر قاهر يقهرهما جميعاً؛ خوفًا على دينهما؛ خوفًا على أنفسهما، فهذا عذر شرعي. وأما التساهل بالشروط فلا، المسلمون عند شروطهم، ويقول عمر : \"مقاطع الحقوق عند الشروط\" فينبغي للمؤمن أن يفي بالشروط، ولا يعجل، ولا يخالف هذا الشرط، ولا يكن مثل المنافقين الذين لا يبالون، بل يلتزم بالشروط، ويقف عندها إلا بأمر ضروري، لا حيلة لهم فيه.","link":"https://binbaz.org.sa/fatwas/1966/حكم-اشتراط-الزوجة-السكن-في-بلد-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_753.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6407,"question":"هل يجوز للفتاة أن تشترط على خاطبها عدم التعدد مطلقًا، أو عدم التعدد بدون مبرر على الأقل؟","title":"حكم اشتراط المرأة على الرجل عدم التعدد","answer":"الجواب: ذكر العلماء أن لها ذلك، لها أن تشرط عليه ألا يتزوج عليها؛ فإن تزوج عليها؛ فلها الخيار، ما يحرم عليه الزواج، لكن لها شرطها، النبي -عليه الصلاة والسلام- قال: المسلمون على شروطهم وقال -عليه الصلاة والسلام-: إن أحق الشروط أن يوفى به ما استحللتم به الفروج.  وقال عمر : مقاطع الحقوق عند الشروط، فإذا شرطت عليه أن لا يتزوج عليها؛ فلها شرطها، فإن صبر به، وثبت عليه؛ فهي زوجته، وإن أبى وأراد الزواج؛ فلها الخيار: إن شاءت بقيت، وإلا فسخ نكاحها منه عملًا بالشرط. السؤال: الشرط أليس غير مشروع؛ لأنه يناقض الإباحة التي يبيحها الإسلام؟ الجواب: هي ما حرمت عليه، هي ما تريد يتزوج عليها، فهو إن شاء قبل، وإن شاء رد ذلك، وترك ذلك. السؤال: يعني كأنها.... الجواب: لا، ما يخالف الحديث كل شرط ليس في كتاب فهو باطل هذا حق لها إذا طلبته؛ فلها ذلك، وهو مخير إن شاء قبل، وإن شاء ترك، ما هو ملزم به حتى ولو بعد العقد.","link":"https://binbaz.org.sa/fatwas/2114/حكم-اشتراط-المراة-على-الرجل-عدم-التعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_766.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6411,"question":"إذا تبين بعد الزواج أن أحد الزوجين فيه عيب، أو نقص جنسي، فما هو التعويض للزوج الآخر في هذه الحالة؟","title":"حكم فسخ عقد الزواج لوجود العيب","answer":"الجواب: هذا إذا وجدت عيبًا فيه، أو وجد فيها عيبًا إن اصطلحا، وإلا المحكمة تحكم بينهما، وهذا يحتاج إلى تفصيل، إذا وجدت المرأة في زوجها عيبًا كبرص داخلي، أو تعطل في النكاح، أو ما أشبه ذلك، أو وجد بها عيبًا كبرص داخلي، أو مرضي، شيء داخلي يعيبها؛ فإن اصطلحا فيما بينهما، ورضي كل واحد بالآخر، أو فارقها بنفسه، أو أعطته شيئًا، وفارقها، فالحمد لله، وانتهى الأمر. فأما إن أدى الأمر إلى النزاع، والخصومة، فهذا إلى المحاكم.","link":"https://binbaz.org.sa/fatwas/2117/حكم-فسخ-عقد-الزواج-لوجود-العيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_769.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6412,"question":"... يكون بيد المرأة...؟","title":"حكم جعل العصمة بيد المرأة","answer":"الجواب: ما يصلح هذا، ما يكون بيد المرأة، العصمة بيد الزوج، فإذا أعطاها؛ يكون شرطًا باطلًا، إذا عقد على هذا؛ يكون شرطًا باطلاً، أما الوكالة إذا وكلها في بعض الأحيان؛ فما في بأس.","link":"https://binbaz.org.sa/fatwas/2119/حكم-جعل-العصمة-بيد-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_770.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6437,"question":"ما رأي سماحتكم في القائمة التي يكتبها أهل الزوجة على العريس، وتكون بالعكس الجهاز حتى إذا طلقها كان لها الحق في كل هذا العكس، هل هذا صحيح؟","title":"وجوب الوفاء بالشروط التي بين الزوجين","answer":"الجواب:\n\nلا بأس فيما يصطلحان عليه، لكن ينبغي لهما عدم التشديد، وينبغي أن يرفق بالزوج حتى لا ينفروا الناس من الخطبة، ومن بناتهم، ينبغي لأهل المرأة ألا يشددوا في هذه المسائل، وكما سمعتم في الندوة أن الخطباء، والنصحاء قد جدوا في هذا الأمر، ولكن قلَّ المستجيب. \n\nفالمشروع للمؤمن ألا يتكلف في المهر، ولا في الوليمة، لا من جهة الزوج، ولا من جهة الزوجة، بل ينبغي لأهل الزوج، والزوجة جميعاً أن يتعاونوا على الاقتصاد، وعدم التكلف؛ حتى يفسح المجال للناس في الزواج، وحتى يتيسر للشباب الزواج، وللفتيات الزواج. \n\nأما مع التكلف في المهور، والتكلف في الولائم فكل هذه عقبات -كما تقدم غير مرة- أن هذه عقبات ينبغي أن تزال، ينبغي للمؤمنين أن يتبصروا، وأن يعرفوا مصيبتهم، وأن يعرفوا داءهم؛ حتى يبصروا دواءهم.\n\nولا شك أن من الأدواء التكلف في المهور، والتكلف في الولائم، والتكلف في إيجاد المغنيات، والمطربات التي تضر، ولا تنفع، ونعوذ بالله، فينبغي في هذا للمؤمنين، والمؤمنات التعاون، على الزوج وأهله، والزوجة وأهلها، والجيران، والأقارب يتعاونون في كل شيء، من تخفيف المهور، وعدم التكلف في المهور، ومن تخفيف الولائم، وأن تكون وليمة مناسبة خفيفة للزوجين، وأقاربهما من غير إسراف؛ حتى لا يتكلف هؤلاء، ولا هؤلاء.\n\nوأما إذا اتفقوا على قائمة يعطيها كذا وكذا، عشرة آلاف ريال، خمسة آلاف ريال، غرفة نوم، حلية كذا وكذا بينهما متفق عليه، ما في شيء اتفقا على هذا؛ فالمسلمون على شروطهم، والنبي -عليه الصلاة والسلام- قال: إن أحق الشروط أن يوفى به ما استحللتم به الفروج متفق على صحته. أحق الشروط ما استحل به الزوج الفرج، فإذا شرط لها شيئًا، شرط لها سلعة معينة، شرط لها دراهم معلومة، وتم الزواج على ذلك، وجب عليه أن يوفي، وليس له التأخر عن ذلك؛ لأنه  استحل فرجها بهذا الأمر.","link":"https://binbaz.org.sa/fatwas/2157/وجوب-الوفاء-بالشروط-التي-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_798.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6450,"question":"ما رأي سماحتكم في القائمة التي يكتبها أهل الزوجة على العريس، وتكون بالعكس الجهاز حتى إذا طلقها كان لها الحق في كل هذا العكس، هل هذا صحيح؟","title":"وجوب الوفاء بالشروط التي بين الزوجين","answer":"الجواب:\n\nلا بأس فيما يصطلحان عليه، لكن ينبغي لهما عدم التشديد، وينبغي أن يرفق بالزوج حتى لا ينفروا الناس من الخطبة، ومن بناتهم، ينبغي لأهل المرأة ألا يشددوا في هذه المسائل، وكما سمعتم في الندوة أن الخطباء، والنصحاء قد جدوا في هذا الأمر، ولكن قلَّ المستجيب. \n\nفالمشروع للمؤمن ألا يتكلف في المهر، ولا في الوليمة، لا من جهة الزوج، ولا من جهة الزوجة، بل ينبغي لأهل الزوج، والزوجة جميعاً أن يتعاونوا على الاقتصاد، وعدم التكلف؛ حتى يفسح المجال للناس في الزواج، وحتى يتيسر للشباب الزواج، وللفتيات الزواج. \n\nأما مع التكلف في المهور، والتكلف في الولائم فكل هذه عقبات -كما تقدم غير مرة- أن هذه عقبات ينبغي أن تزال، ينبغي للمؤمنين أن يتبصروا، وأن يعرفوا مصيبتهم، وأن يعرفوا داءهم؛ حتى يبصروا دواءهم.\n\nولا شك أن من الأدواء التكلف في المهور، والتكلف في الولائم، والتكلف في إيجاد المغنيات، والمطربات التي تضر، ولا تنفع، ونعوذ بالله، فينبغي في هذا للمؤمنين، والمؤمنات التعاون، على الزوج وأهله، والزوجة وأهلها، والجيران، والأقارب يتعاونون في كل شيء، من تخفيف المهور، وعدم التكلف في المهور، ومن تخفيف الولائم، وأن تكون وليمة مناسبة خفيفة للزوجين، وأقاربهما من غير إسراف؛ حتى لا يتكلف هؤلاء، ولا هؤلاء.\n\nوأما إذا اتفقوا على قائمة يعطيها كذا وكذا، عشرة آلاف ريال، خمسة آلاف ريال، غرفة نوم، حلية كذا وكذا بينهما متفق عليه، ما في شيء اتفقا على هذا؛ فالمسلمون على شروطهم، والنبي -عليه الصلاة والسلام- قال: إن أحق الشروط أن يوفى به ما استحللتم به الفروج متفق على صحته. أحق الشروط ما استحل به الزوج الفرج، فإذا شرط لها شيئًا، شرط لها سلعة معينة، شرط لها دراهم معلومة، وتم الزواج على ذلك، وجب عليه أن يوفي، وليس له التأخر عن ذلك؛ لأنه  استحل فرجها بهذا الأمر.","link":"https://binbaz.org.sa/fatwas/2157/وجوب-الوفاء-بالشروط-التي-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_798.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6669,"question":"ألا يكون تعدد الزوجات سببًا لقلة راحة الرجل من خلال المشاجرات، وكره، وبغض الأولاد الذين هم من إحدى الزوجات من قبل الزوجة الأخرى سببًا يكره الأولاد آباءهم، أفتونا جزاكم الله خيرًا؟","title":"هل التعدد سبب للمشاكل","answer":"الجواب: هذا السؤال ناشئ عن تشبيه أعداء الله، وتلبيس أعداء الله، فليس هناك مشاكل، وليس هناك عداوة بين الأولاد، بل بينهم المحبة، والتعاون، والخير، وليس هناك مشاكل إلا من الزوج، هو هو صاحب المشاكل، فإذا عدل؛ فلا مشاكل.","link":"https://binbaz.org.sa/fatwas/2573/هل-التعدد-سبب-للمشاكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1068.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6683,"question":"هل التعدد أصل في الشريعة، أم الواحدة؟ وهل العدل يعني كل شيء أو أشياء مخصصة؟","title":"التعدد هو الأصل في الشريعة","answer":"الجواب: الأصل التعدد، والواحدة عند العجز، والذين لا يعددون -ولاسيما من أعداء الإسلام هم أشباه الأنعام- يقتصرون على واحدة في الاسم، وهم في الحقيقة ليسوا على واحدة، بل على عدد كالتيس الذي يعرض عليه هذه وهذه، ويلقي منيه ونطفته في كل مكان ولا يبالي كالبهيمة، أما صاحب الزوجات في الشرع فهو يلقيها في محل صالح، في محل أباحه الله، في محل مخصوص، وهو بعيد عن مشابهة البهائم، ولكن هم -أعداء الله- أقرب الناس إلى مشابهة البهائم، كما قال : أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلَّا كَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ سَبِيلًا [الفرقان:44]. السؤال: في الخارج يتزوج الرجل على واحدة امرأة، يقولون: عندهم القانون لا يبيح لهم أكثر من ذلك، وإذا أراد ان يتزوج؛ يتزوج متعة ما الحكم في هذا؟ الجواب: هذا عند الرافضة، المتعة عند الرافضة ما هي عند النصارى وأشباههم، النصارى عندهم الزنا.","link":"https://binbaz.org.sa/fatwas/2571/التعدد-هو-الاصل-في-الشريعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1066.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6691,"question":"إذا ولشت المرأة عن الرجل في عيب من العيوب، علمًا بأنه لم يكتشف هذا العيب إلا بعد الدخول بها، فهل هذا يبرر إنهاء العلاقة؟","title":"حكم من اكتشف عيباً في زوجته بعد الدخول بها","answer":"الجواب: هذا بينه وبينها، إن شاء فارقها، وإن شاء اتصل بالمحكمة، والمحكمة تنظر في الأمر، هذا بينه، وبين المرأة، إذا عرف عيبًا فليس كل عيب يوجب الفسخ، وليس كل عيب يقتضي الترافع إلى المحكمة، بل هذا بين الزوج، والزوجة، إن رأى عيبًا يمكن الصبر عليه؛ صبر، وإن رأى عيبًا يوجب الفسخ؛ سأل أهل العلم، وسأل المحكمة، وعرض عليها الأمر، وإذا أحسن، وطلق من غير شيء، وإلا اتفق معهم على شيء يرضونه به، وطلق، هذه أمور داخلية بين الرجل، وأهل المرأة، والمرأة.","link":"https://binbaz.org.sa/fatwas/2572/حكم-من-اكتشف-عيبا-في-زوجته-بعد-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1067.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6725,"question":"استدلت بعض طوائف الشيعة على جواز الزواج بتسع، وأخذوا بالجمع بين الألفاظ الواردة في الآية مثنى، وثلاث، ورباع، ومجموعها تسع، فما رد سماحتكم؟","title":"الرد على من أجاز التزوج بتسع نسوة","answer":"الجواب: الرافضة قولهم لا يلتفت إليه، وهكذا من شذ من غيرهم، فقال بالتسع، كله قول مرفوض عند أهل العلم، وليس له نصيب من النصيحة، والذي عليه أهل العلم -وهو كالإجماع منهم- أنه لا يجوز أبدًا إلا أربع فقط، وأما التسع فهي خاصة بالنبي -عليه الصلاة والسلام- والرافضة لهم زلات كثيرة، وأخطاء كثيرة، وكثير منهم يبيح نكاح المتعة، وهو محرم بالنص من الرسول ﷺ وبإجماع أهل السنة، نكاح المتعة محرم عند أهل السنة، والجماعة، وبالنص عن رسول الله ﷺ فإنه لما حرم المتعة قال: فإن الله قد حرم ذلك إلى يوم القيامة وكثير من المرات كانوا يحلون المتعة، وربما تمتع بها وهي عندها زوج، ولا حول ولا قوة إلا بالله. المقصود: أن نكاح المتعة هو أن ينكحها على مدة شهرين، أو ثلاث، أو أربع إلى أجل معلوم، تمكنه من نفسها على شهرين، أو ثلاثة بدون ولي، وبدون شهود، هذا من أبطل الباطل، هذا هو الزنا، نسأل الله السلامة. السؤال: في صحيح البخاري عن أحد الصحابة  يقول: كنا مع الرسول في غزوة، فطالت علينا... ما معنى هذا الكلام؟ الجواب: يعني أباح لهم نكاح المتعةـ ثم نسخ المتعةـ كانت مباحة في أول الإسلام، ثم نسخها الله في آخر الإسلام، وحرمها، كان مباح لهم أن يتزوجون نكاح المتعة شهرين، ثلاثة، أربعة في الأسفار، ثم نسخ هذا، وحرمه الله إلى يوم القيامة.","link":"https://binbaz.org.sa/fatwas/2601/الرد-على-من-اجاز-التزوج-بتسع-نسوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1097.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6734,"question":"استدلت بعض طوائف الشيعة على جواز الزواج بتسع، وأخذوا بالجمع بين الألفاظ الواردة في الآية مثنى، وثلاث، ورباع، ومجموعها تسع، فما رد سماحتكم؟","title":"الرد على من أجاز التزوج بتسع نسوة","answer":"الجواب: الرافضة قولهم لا يلتفت إليه، وهكذا من شذ من غيرهم، فقال بالتسع، كله قول مرفوض عند أهل العلم، وليس له نصيب من النصيحة، والذي عليه أهل العلم -وهو كالإجماع منهم- أنه لا يجوز أبدًا إلا أربع فقط، وأما التسع فهي خاصة بالنبي -عليه الصلاة والسلام- والرافضة لهم زلات كثيرة، وأخطاء كثيرة، وكثير منهم يبيح نكاح المتعة، وهو محرم بالنص من الرسول ﷺ وبإجماع أهل السنة، نكاح المتعة محرم عند أهل السنة، والجماعة، وبالنص عن رسول الله ﷺ فإنه لما حرم المتعة قال: فإن الله قد حرم ذلك إلى يوم القيامة وكثير من المرات كانوا يحلون المتعة، وربما تمتع بها وهي عندها زوج، ولا حول ولا قوة إلا بالله. المقصود: أن نكاح المتعة هو أن ينكحها على مدة شهرين، أو ثلاث، أو أربع إلى أجل معلوم، تمكنه من نفسها على شهرين، أو ثلاثة بدون ولي، وبدون شهود، هذا من أبطل الباطل، هذا هو الزنا، نسأل الله السلامة. السؤال: في صحيح البخاري عن أحد الصحابة  يقول: كنا مع الرسول في غزوة، فطالت علينا... ما معنى هذا الكلام؟ الجواب: يعني أباح لهم نكاح المتعةـ ثم نسخ المتعةـ كانت مباحة في أول الإسلام، ثم نسخها الله في آخر الإسلام، وحرمها، كان مباح لهم أن يتزوجون نكاح المتعة شهرين، ثلاثة، أربعة في الأسفار، ثم نسخ هذا، وحرمه الله إلى يوم القيامة.","link":"https://binbaz.org.sa/fatwas/2601/الرد-على-من-اجاز-التزوج-بتسع-نسوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1097.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6755,"question":"ما حكم الزواج من بنت العم أو بنت الخال؟","title":"حكم الزواج من بنت العم والخال والجمع بينهما","answer":"الجواب: لا حرج في الزواج من بنت العم، وبنت الخال، الله أباح ذلك  ونكح النبي ﷺ ببنات عمه -عليه الصلاة والسلام- فالممنوع الأختين، الجمع بين الأختين، والجمع بين الخالة، وعمتها، والمرأة، وخالتها، هذا هو الممنوع، أما بنات العم، وبنات الخال؛ فلا بأس، وبنات الخالة، وبنات العمة؛ فلا حرج في زواجهن، والجمع بينهن.","link":"https://binbaz.org.sa/fatwas/2635/حكم-الزواج-من-بنت-العم-والخال-والجمع-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1131.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6766,"question":"ما حكم الزواج من بنت العم أو بنت الخال؟","title":"حكم الزواج من بنت العم والخال والجمع بينهما","answer":"الجواب: لا حرج في الزواج من بنت العم، وبنت الخال، الله أباح ذلك  ونكح النبي ﷺ ببنات عمه -عليه الصلاة والسلام- فالممنوع الأختين، الجمع بين الأختين، والجمع بين الخالة، وعمتها، والمرأة، وخالتها، هذا هو الممنوع، أما بنات العم، وبنات الخال؛ فلا بأس، وبنات الخالة، وبنات العمة؛ فلا حرج في زواجهن، والجمع بينهن.","link":"https://binbaz.org.sa/fatwas/2635/حكم-الزواج-من-بنت-العم-والخال-والجمع-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1131.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6772,"question":"أنا متزوج، وأريد منع زوجتي من الدراسة النظامية؛ لأنه يترتب على ذلك إهمال الحقوق الزوجية، وعدم القيام بها، فما فتواكم في هذا؟","title":"حكم منع الزوج زوجته من الدراسة","answer":"الجواب:  لا حرج إذا منعها الزوج من الدراسة، وقد حصل لها ما ينفعها من جنس المبادئ الدينية، فالحمد لله كافي إلا إذا كان مشروطًا عليه في الزواج، إذا كان مشروطًا عليه أن يبقيها حتى تكمل الدراسة الثانوية، أو الجامعية، فالمسلمون على شروطهم، أما إذا كان بدون شروط؛ فله أن يمنعها، وله أن يسمح لها بشروط الالتزام بالحجاب وعدم الخلوة بالأجنبي، فإذا سمح لها مع إكمال الشروط الشرعية؛ فلا بأس، وإن منعها؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/2658/حكم-منع-الزوج-زوجته-من-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1154.mp3","categories":["الحقوق الزوجية","الشروط والعيوب في النكاح"]},{"id":6779,"question":"زوجتي اشترطت في عقد الزوج أن تعمل، وبعد أن أنجبت طفلين أمرتها أن تترك العمل؛ فرفضت، وحصلت مشاكل كثيرة، وأنا الآن أمام أمرين: إما أن تعمل، أو أن أطلقها، أرشدوني جزاكم الله خيرًا؟","title":"حكم منع الزوجة من العمل رغم اشتراطها ذلك عند العقد","answer":"الجواب: اعمل الأصلح، إذا كانت طيبة، وجيدة، ومتأدبة بالآداب الإسلامية، وترغب في العمل لأجل الحاجة إلى المال، واكتساب المال، وهي مستقيمة في دينها، ويمكن أن تقوم بالأمرين؛ فلا بأس.  وإن لم يكن ذلك فالحمد لله، تسلك مسلكًا آخر، التمس زوجة صالحة طيبة تقوم بحاجتك، وهذه طلقها، وكلا يغنه الله من سعته، يقول الله سبحانه: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130] فانظر ما هو أصلح لقلبك، وأصلح لدينك نفعًا من طلاق، أو بقاء.","link":"https://binbaz.org.sa/fatwas/2659/حكم-منع-الزوجة-من-العمل-رغم-اشتراطها-ذلك-عند-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1155.mp3","categories":["الحقوق الزوجية","الشروط والعيوب في النكاح","قضايا المرأة"]},{"id":6949,"question":"كثيرًا ما نرى الإخوة الميسر لهم المال من المسلمين يقدمون على الزواج من الثانية، والثالثة، وهناك كثير من بلاد المسلمين، شباب مسلم، متدين، وفتيات مسلمات لا يجدن القدرة على الزواج بواحدة فقط؛ لعدم توفر المسكن الذي يؤويهما، وعدم القدرة على الإنفاق، أليس الأولى مساعدة هؤلاء الشباب، والشابات من المتدينين بالزواج، وعصمتهم من الوقوع في الإثم والمعصية؟","title":"حكم الزواج بأكثر من واحدة وهناك من لا يستطيع الزواج","answer":"الجواب: يقول النبي ﷺ: ابدأ بنفسك، ثم من تعول ابدأ بنفسك، ثم من تعول، إذا كنت أيها السائل نشيطًا؛ زوج من شئت من الناس، وتقتصر على واحدة -إذا كان يسدك الواحدة.  أما واحد ما تسده الواحدة، ولا تكفيه واحدة، يريد أن يعف نفسه، وأن يتباعد عن الحرام؛ فله أن يتزوج ثنتين، أو ثلاثًا.  ولو كان في باكستان، أو في أفغانستان، أو في مصر، أو في الشام، أو أنت في بلادك، شباب لم يستطيعوا الزواج، لا يلزمه تزويجهم، عليهم أن يعملوا، ويتزوجوا، وعلى أقاربهم أن يزوجوهم، أما هذا الشخص الذي محتاج للزوجة، ما يلزمه يزوج الآخرين، يبدأ بنفسه.","link":"https://binbaz.org.sa/fatwas/2879/حكم-الزواج-باكثر-من-واحدة-وهناك-من-لا-يستطيع-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1327.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6956,"question":"يلاحظ في مجتمعنا المسلم ظاهرة خطيرة، وهي الإنكار على كل شخص يحاول أن يتزوج مرة ثانية، فأين دور العلماء الكرام في توعية هذا المجتمع؟ فأنا شاب مسلم، ومتزوج -ولله الحمد- أبحث عن زوجة أخرى، فلم أجد حتى أذنًا صاغية، فالكل يسفهني، فكيف نرضى ببعض الكتاب، ونعرض عن بعض؟","title":"القول فيمن ينكر على من أراد التعدد","answer":"الجواب: يسر الله أمرك، سمعت المحاضرة التي تؤكد ما قلته، وتأمر بالسماح، وهذا مما يتعلق بالعلماء، سمعت المحاضرة الآن، والتعليق عليها، وأنت -إن شاء الله- تعلق بعدين في المجتمعات؛ لأن القاعدة كما تقدم فليبلغ الشاهد الغائب.  سمعتم المحاضرة الآن، وسمعتم التعليق؛ فعليكم أن تبلغوا، فأنت واحد منهم فليبلغ الشاهد الغائب بلغوا من وراءكم من مجتمعاتكم، وأهليكم، وقبائلكم أن التعدد لا بأس به، وأنه مشروع مع تحري العدل، ومع تقوى الله في ذلك، وبلغوا النساء لا يأبين هذا، ويصبرن، ويحتسبن؛ حتى يكثر المتزوجون، وتقل العوانس، ويقل الشباب المتأخر عن الزواج، هذا إذا حضر التعاون مع الحرص على تخفيف المهور، وتقليل الولائم، يعني التناصح في هذا أن تكون المهور قليلة، وأن تكون الولائم قليلة؛ حتى لا يشق على الزوج، وحتى لا يكلف ما يمنعه من الزواج -نسأل الله للجميع التوفيق-.","link":"https://binbaz.org.sa/fatwas/2886/القول-فيمن-ينكر-على-من-اراد-التعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1334.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":7434,"question":"رجل عنده أربع زوجات وجارية، وأنجبت الجارية، فهل يطلق واحدة، وهل إذا تزوج الجارية وأعتقها لا بد أن يطلق واحدة من الأربع؟","title":"حكم اقتناء جارية زيادة على أربع زوجات","answer":"الجواب: ليس له إلا أربع زوجات، وإذا كان عنده جارية مملوكة ما تحسب من الزوجات؛ لأن الله -جل وعلا- قال: فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3] فالعدد من المماليك لا يضر، العدد إنما هو في الزوجات، في الأحرار أربع فأقل، ولو كان عنده معهن خمس إماء أو عشر إماء لا يضره، لكن إذا أعتقها، وجعل عتقها صداقها، وتزوجها؛ فلا بد أن تكون رابعة، ما تكون خامسة، إذا تزوجها على أنها خامسة ما يصلح، يبطل هذا العقد، ليس له إلا أربع.","link":"https://binbaz.org.sa/fatwas/3522/حكم-اقتناء-جارية-زيادة-على-اربع-زوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1826.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":7550,"question":"الرسالة الأولى وردتنا من المرسل فهد هايل شايم العنزي من الحدود الشمالية طريف، يقول في رسالته: السلام عليكم ورحمة الله وبركاته، وبعد: إن بعض الآباء حينما يزوج ابنته يشترط على الزوج إذا طلق ابنته بعد الزواج أن يدفع مبلغ مائة ألف ريال مثلاً، هل هذا يجوز أم لا، علماً بأن زوجها الذي يطلقها لن يؤدي واجباً نحو هذا الزوج، أفيدوني جزاكم الله خير ودمتم؟","title":"حكم اشتراط المهر المؤخر عند الطلاق","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلم يثبت في الشرع المطهر تحديد للمهور بل ما تراضى عليه الزوج وولي المرأة من المهر فلا بأس، قل أو كثر، ولكن دلت السنة في أحاديث كثيرة على شرعية التقليل من المهور وعدم التكلف والمغالاة، هذا هو السنة، لما في ذلك من تشجيع الزواج وإعفاف الشباب والفتيات، وتسهيل هذا الأمر الشرعي، فالمغالاة من أسباب تعطيل الرجال والنساء جميعاً، لا من جهة المهور ولا من جهة الولائم، والتساهل في المهور والولائم، والتخفيف في ذلك والتيسير في ذلك هو الذي ينبغي، وهو من أعظم الأسباب في تكثير النكاح، وتقليل السفاح، ومن أعظم الأسباب لعفة الرجال والنساء، ومن أعظم الأسباب لكثرة الأمة، فينبغي لكل مسلم أن يعتني بهذا، وأن يحرص على التخفيف والتيسير في المهور والولائم مهما أمكن ذلك، وإذا اتفق الزوجان على مهر معين ولو كان كثيراً لزم، على حسب الشروط؛ لقول النبي عليه الصلاة والسلام: إن أحق الشروط أن يوفى به ما استحللتم به الفروج متفق عليه.\nفإذا شرط عليه مالاً معيناً يدفعه عند الطلاق ودخل على ذلك لزم، فإذا زوجه على أنه يدفع لها أولاً مثلاً خمسة آلاف، وعند الطلاق عشرة آلاف أو عشرين ألفاً، أو أكثر أو أقل، فإنه يلزمه، ويكون المال المعين الأخير مؤجلاً إلى الطلاق، ويلزم الزوج إذا طلق أن يؤديه إلا إذا سمحت المرأة الرشيدة بذلك، وأعفته من ذلك فلا بأس؛ لأن الله سبحانه يقول: وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237]، فإذا سمحت وعفت وطابت نفسها بشيء من المهر فلا بأس؛ لقول الله : فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4].\nفالمقصود أن الشروط التي تكون بين الزوجين في النكاح معتبرة ولازمة إذا كانت موافقة للشرع المطهر، ومن ذلك شرط المهر المعين، المعجل والمؤجل، هذا هو الصواب. نعم.","link":"https://binbaz.org.sa/fatwas/4537/حكم-اشتراط-المهر-الموخر-عند-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_013/01301.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":7646,"question":"هذه أيضاً رسالة فيها استفسار عن التهاون بالصلاة، بعث بها المستمع محمد بن حزام بن موسى الشهري من نجران، يقول: ما حكم من ترك الصلاة تكاسلاً حتى يخرج وقتها؟ هل عليه إثم في ذلك، وهل تنطبق عليه صفات المنافقين، أفتونا مشكورين؟","title":"ما حكم ترك الصلاة تكاسلًا؟","answer":"الجواب: تأخير الصلاة جريمة عظيمة ومنكر عظيم، وقد ذهب جمع من أهل العلم إلى من أن ترك الصلاة عمداً حتى خرج وقتها أنه يكفر بذلك كفراً أكبر وردة عن الإسلام -نعوذ بالله- ويحتجون على هذا بما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، هذا ظاهره أنه يكفر بذلك إذا أخرها حتى خرج وقتها، وقال أيضاً عليه الصلاة والسلام العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقال: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله فتأخيرها جريمة عظيمة ومنكر عظيم، فالذي -مثلاً- يؤخر الفجر حتى يصليها الضحى، هذا منكر عظيم يجب أن يصليها قبل طلوع الشمس، ويجب أن يهتم بذلك، وهو مع كونه أتى جريمة قد تشبه بالمنافقين، وقد كفره جماعة من أهل العلم بذلك.\nفالواجب على المسلم أن يعتني بالصلاة وأن يؤديها في الوقت مع المسلمين في الجماعة في المساجد، وليس له تأخيرها أبداً لا مع المسلمين ولا في البيت بل يجب أن يبادر حتى يؤديها في الوقت مع المسلمين في مساجد الله، والمرأة كذلك عليها أن تبادر بأن تصلي الصلاة في وقتها في بيتها، ولا يجوز لها التأخير، كما يفعل بعض الطالبات تؤخر الصلاة حتى تقوم بعد طلوع الشمس للمدرسة ثم تصلي، هذا لا يجوز، هذا منكر عظيم، وهكذا بعض المدرسات تؤجل الصلاة صلاة الفجر إلى أن تطلع الشمس ثم تقوم للتدريس وللصلاة، هذا منكر عظيم يجب أن تصلى الصلاة في وقتها قبل طلوع الشمس، وإذا كانت يغلبها النوم فيجب أن تتخذ ما يعينها على اليقظة مثل ساعة منبهة تؤكد على وقت الصلاة، أو تستعين بأهل البيت يوقظونها حتى تصلي الصلاة بوقتها، وهكذا العشاء لا تؤخر إلى بعد نصف الليل، وقت العشاء ينتهي إلى نصف الليل، هذا وقتها الاختياري، وكذلك المغرب لا تؤخر حتى يغيب الشفق وتصلى قبل الشفق، والشفق: الحمرة التي تكون في المغرب، يجب أن تصلي المغرب قبل ذلك قبل أن يغيب الشفق، وهكذا عند الظهر لا تؤجل حتى يصير ظل كل شيء مثله ما بعد فيء الزوال بل تصلى في أول الوقت بعد الزوال، والعصر لا تؤجل حتى تصفر الشمس بل تؤدى في وقتها، النبي ﷺ كان يؤديها في الوقت، ولما سئل عن ذلك صلى الصلاة يوماً في أول وقتها ثم صلاها في آخر وقتها، يعني الصلوات الخمس، ثم قال:: الصلاة بين هذين الوقتين، والله يقول سبحانه: إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103] يعني مفروضاً في الأوقات، فالله يخبر أنها مفروضة في الأوقات، فلا يجوز لأهل الإسلام أن يؤخروها عن أوقاتها، بل يجب أن تؤدى في الوقت، ويروى عن عمر  ما يدل على الشدة في ذلك وهو كما قال  وأرضاه، وثبت عنه ﷺ أيضاً في حديث عبد الله بن عمرو بن العاص أنه قال عليه الصلاة والسلام: من حافظ على الصلاة كانت له نوراً وبرهاناً ونجاة يوم القيامة، ومن لم يحافظ عليهاا لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف-نسأل الله العافية- هؤلاء كبار الكفار ومن صناديدهم -نعوذ بالله-.\nقال بعض أهل العلم: إنه يحشر من ضيع الصلاة مع هؤلاء؛ لأنه إذا ضيعها من أجل الرياسة حشر مع فرعون ، وإن ضيعها من أجل الوزارة ونحوها حشر مع هامان وزير فرعون ، وإن ضيعها من أجل الشهوات والنعم والمال حشر مع قارون الذي أعطاه الله المال، فبطر وتكبر وعصى نبي الله موسى ، فخسف الله به وبداره الأرض -نسأل الله العافية- عقوبة عاجلة مع النار، وإن ترك الصلاة وضيعها بسبب أعمال التجارة والبيع والشراء حشر يوم القيامة مع أبي بن خلف تاجر أهل مكة.\nفالواجب على أهل الإسلام الحذر غاية من التساهل بالصلاة، والواجب أن تؤدى في أوقاتها، المرأة تؤديها في الوقت، والرجل يؤديها في جماعة في المساجد، ولا يجوز التشبه بالمنافقين في التساهل بالصلاة، وعرفت أن بعض أهل العلم يقول: إن من تركها تهاوناً حتى خرج الوقت كفر بذلك، وهذا القول قول صحيح، ترك الصلاة تهاون وتساهل بها كفر أكبر -نسأل الله العافية- فإن السنة تؤيده، السنة عن رسول الله ﷺ تؤيد هذا القول، فإن الباب فيه أحاديث صحيحة كما تقدم، فيجب على المسلم أن يحذر هذا الأمر الخطير، وأن يحافظ على الصلاة في وقتها، وأن يستعين على ذلك بكل ما يستطيع من ساعة وغيرها، حتى يؤدي الصلاة في وقتها مع إخوانه المسلمين، وحتى تؤدي المرأة صلاتها في وقتها في بيتها قبل خروج الوقت، فهي عمود الإسلام وهي أهم الفرائض بعد الشهادتين، نسأل الله للجميع الهداية والتوفيق. نعم.\nالمقدم: أحسنتم أثابكم الله.","link":"https://binbaz.org.sa/fatwas/4786/ما-حكم-ترك-الصلاة-تكاسلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03507.mp3","categories":["الشروط والعيوب في النكاح","حكم الصلاة وأهميتها"]},{"id":7973,"question":"وبقي له سؤال أيضاً يقول: هل يجوز الأكل والشرب في بيت شخص لا يؤدي الصلاة ولا الصيام علماً أن عمره يتجاوز أربعين سنة، فما حكم ذلك وفقكم الله، هذا ولكم الشكر؟","title":"حكم مؤاكلة ومجالسة تارك الصلاة والصيام","answer":"الجواب: الذي لا يصلي لا يجوز أن تجاب دعوته ولا أن يقصد شرب قهوته ولا الأكل من وليمته، بل يجب أن يهجر ويجب أن يستتاب حتى يرجع عن باطله، فإن الصلاة هي عمود الإسلام، ومن تركها كفر نسأل الله العافية، فالذي يتركها يجب أن يهجر بين المسلمين، ولا يزار، ولا تجاب دعوته، ولا يسلم عليه، ولا يرد عليه السلام؛ لأنه ترك عمود الإسلام، ولأنها أعظم الأركان بعد الشهادتين؛ ولهذا قال عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة وقال عليه الصلاة والسلام أيضاً: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.\nفالذي يتركها عمداً كافر نسأل الله العافية، يجب أن يهجر وألا يسلم عليه، ولا يرد عليه السلام، ولا تجاب دعوته، ويجب على ولي الأمر أن يستتيبه، فإن تاب ورجع عن باطله وإلا وجب أن يقتل، هذا هو الصواب فيه، وهذا هو الذي عليه جمهور أهل العلم، نسأل الله السلامة والعافية. نعم.","link":"https://binbaz.org.sa/fatwas/5522/حكم-مواكلة-ومجالسة-تارك-الصلاة-والصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_071/07103.mp3","categories":["الشروط والعيوب في النكاح","حكم الصلاة وأهميتها"]},{"id":8035,"question":"هذه رسالة من السائلة فاطمة محمد عبد الله من الإحساء تقول: إني عندي زوج لا يصلي وصار لي من تزوجته سبع وعشرين سنة لا يصلي ولا يصوم من الأول وصار له من بعد خمسة عشر سنة يصلي ويصوم في رمضان فقط ثم يترك الصلاة والصوم، وأنا في قلبي كراهة لله سبحانه وليس عن شيء أكرهه وهو أبو أولادي، ترجو الإفادة منكم يا سماحة الشيخ؟","title":"حكم بقاء الزوجة عند زوج لا يصلي","answer":"الجواب: ترك الصلاة كفر بالله عز وجل، فهذا الذي لا يصلي ما ينبغي لها أن تبقى معه وقد أخبر النبي ﷺ أن ترك الصلاة كفر فقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة هذا الذي لا يصلي لا ينبغي للمرأة أن تبقى معه بل ينبغي لها أن تفارقه وتعرض أمرها على المحكمة والمحكمة تفرق بينهما؛ لأن هذا كفر عظيم نعوذ بالله، والصحيح أنه كفر أكبر، الصحيح من أقوال العلماء أنه كفر أكبر، وذهب جمع من أهل العلم إلى أنه كفر دون كفر وأنه لا يخرجه من الملة مادام يقر بأن الصلاة واجبة هو يعلم أنها واجبة ولكن حمله التساهل على ذلك فعند جمع من أهل العلم أنه لا يكون كافراً كفراً أكبر.\nولكن بكل حال فهو قد أتى جريمة عظيمة أعظم من الزنا وأعظم من اللواط وأعظم من العقوق، فالواجب على المرأة هذه أن تتقي الله عز وجل وألا تبقى مع هذا الصنف من الناس الذي هو -والعياذ بالله- ضيع عمود الإسلام؛ لأن الله قال في الكفرة: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10].\nفالمسلمة لا تبقى مع الكافر أبداً، والصحيح: أن هذا كافر كفر أكبر نعوذ بالله، فلا يجوز لها أن تبقى معه بل يجب أن تفارقه وأن تعتزله وأن تبغضه في الله عز وجل، وأن تطالب بفراقه لها تطالب ولاة الأمور.. تطالب المحكمة بأن تفرق بينها وبينه لكونه قد أتى أمراً عظيماً اعتبره الكثير من أهل العلم كفراً أكبر، نسأل الله أن يهدينا وإياه، نسأل الله يرده للتوبة، نسأل الله لنا وله الهداية.\nولكن هذه السائلة يجب عليها أن تسعى في فراقه لدى المحكمة إذا كان تركه للصلاة أمراً واضحاً معروفاً فتقيم البينة عليه والمحكمة تفرق بينها وبينه إذا لم يتب، أما إن تاب وهداه الله فالحمد لله.\nوالواجب على ولاة الأمور إذا علموا من يترك الصلاة أن يستتاب فإن تاب وإلا قتل كافراً نعوذ بالله، على الصحيح أو حداً على القول الثاني، وبكل حال فالواجب على من ترك الصلاة أن يتوب إلى الله وأن يبادر بالتوبة، وأن يعلم أنه أتى أمراً عظيماً ومنكراً شنيعاً، فيجب عليه التوبة إلى الله سبحانه والبدار إلى أداء الصلاة والحذر من مشابهة أعداء الله في ترك الصلاة، وقد قال الله عز وجل عن أهل النار : مَا سَلَكَكُمْ فِي سَقَرَ ۝ قالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:42-43] فذكروا أهم الأعمال التي دخلوا بها النار عدم الصلاة نعوذ بالله، نسأل الله العافية.\nالمقدم: أحسنتم أثابكم الله .. شكراً يا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/5659/حكم-بقاء-الزوجة-عند-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_080/08006.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":8106,"question":"شيخ عبد العزيز سبق وأن عرضنا موضوعاً عن عمل المرأة، وها هي الرسائل تستجيب لذالكم الموضوع فمن مشاكل عمل المرأة هذه المشكلة التي تصورها أختنا (س. م. س) من المنطقة الشرقية أبقيق، أختنا تقول: إنها معلمة بالمملكة منذ سنوات وتزوجت، وجاء زوجها معها بدلاً من أخيها الذي كان يرافقها أولاً، ورزقنا الله طفلاً والحمد لله، وبدأ زوجي في البحث عن عمل يناسب مؤهله العلمي ولكن لم يوفق، وأخيراً عمل بإحدى المحلات الموجودة بالمنطقة الشرقية التي نعيش فيها، وبدأ الخلاف على مصاريف البيت، فأسأل سماحة الشيخ أولاً: هل علي أن أتحمل في مصاريف البيت؛ لأن زوجي يقول: إذا لم تدفعي في مصاريف البيت فلا عمل لك مطلقاً؟ هل لزوجي حق في مرتبي الذي أتقاضاه مقابل عملي؟ وإذا كان علي أن أتحمل في مصاريف البيت فما هي النسبة بيني وبين زوجي؟ أفيدونا في هذه القضايا لو تكرمتم سماحة الشيخ؟","title":"حكم أخذ الزوج من راتب زوجته","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه المسألة وهي مصاريف البيت بين الزوج والزوجة اللذين تغربا للعمل وطلب الرزق ينبغي فيها المصالحة بينهما وعدم النزاع، أما من حيث الواجب فهذا يختلف، فيه تفصيل: إن كان الزوج قد شرط عليك أن المصاريف بينك وبينه وإلا لم يسمح لك بالعمل فالمسلمون على شروطهم، يقول النبي ﷺ: المسلمون على شروطهم إلا شرطاً حرم حلالاً أو أحل حراماً، ويقول ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج، فأنتما على شروطكما، إن كان بينكما شروط.\nأما إذا لم يكن بينكما شروط فالمصاريف كلها على الزوج وليس على الزوجة مصاريف البيت، فهو الذي ينفق، قال الله جل وعلا: لِيُنفِقْ ذُو سَعَةٍ مِنْ سَعَتِهِ [الطلاق:7] وقال النبي ﷺ: وعليكم رزقهن وكسوتهن بالمعروف فالنفقة على الزوج هو الذي يقوم بحاجات البيت وشئون البيت له ولزوجته وأولاده ومعاشها لها وراتبها لها لأنه في مقابل عملها وتعبها، وقد دخل على هذا ولم يشرط عليها أن المصاريف عليها أو نصفها أو نحو ذلك، أما إن كان دخل على شيء فمثل ما تقدم المسلمون على شروطهم.\nوإذا كان قد دخل على أنك مدرسة وعلى أنك تعملين ورضي بذلك فإنه يلزمه الخضوع لهذا الأمر وأن لا ينازع في شيء من ذلك وأن يكون راتبك لك إلا إذا سمحت بشيء من الراتب عن طيب نفس فالله جل وعلا يقول: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4] وينبغي لك أن تسمحي ببعض الشيء، وأنا أنصح لك أن تسمحي ببعض الراتب لزوجك تطييباً لنفسه وحلاً للنزاع وإزالة للإشكال حتى تعيشا في هدوء وراحة وطمأنينة، فاتفقا على شيء بينكما كنصف الراتب أو ثلثه أو ربعه ونحو ذلك، حتى تزول المشاكل، وحتى يحل الوئام والراحة والطمأنينة محل النزاع.\nأما إن لم يتيسر ذلك فلا مانع من التحاكم إلى المحكمة ورفع القضية إلى المحكمة في البلد التي أنتم بها، وفيما تراه المحكمة الشرعية الكفاية إن شاء الله. ولكن نصيحتي لكما جميعاً هو الصلح وعدم النزاع وعدم الترافع إلى المحكمة وأن ترضي -أيها الزوجة- بشيء من المال لزوجك حتى يزول الإشكال أو يسمح هو ويرضى بما قسم الله له، ويقوم بالنفقة حسب طاقته ويسمح عن راتبك كله ويترفع عن ذلك، هذا هو الذي ينبغي بينكما، ولكني أنصح وأكرر أن تسمحي أنت ببعض الراتب حتى تطيب نفسه وحتى تتعاونا على الخير بينكما، فالبيت بيتكما والأولاد أولادكما والشيء لكما، فالذي ينبغي التسامح منك ببعض الشيء حتى يزول الإشكال، وفق الله الجميع.\nالمقدم: وقت المرأة سماحة الشيخ أهو لها أم لزوجها، الوقت؟\nالشيخ: الوقت لزوجها، إلا إذا سمح أو دخل على ذلك، دخل على أنها مدرسة أو طالبة فعليه أن يمكنها من شرطها.\nأما إذا كان لم يدخل على هذا الشرط ولكنه سمح بأن تدرس فله أن يرجع عن هذا السماح، له أن يرجع ويمنعها من التدريس إلا أن يصطلحا على شيء بينهما، كأن يصطلحا على نصف الراتب للبيت أو ثلث الراتب فلا بأس.\nالمقدم: بارك الله فيكم، إذاً ليس للمرأة أن تؤجر نفسها بدون إذن زوجها؟\nالشيخ: نعم نعم، ليس لها ذلك إلا بإذنه إلا إذا شرط ذلك عليها وقت العقد، أنها تدرس أو أنها تعمل كذا وتعمل كذا والتزم بذلك، فالمسلمون على شروطهم.","link":"https://binbaz.org.sa/fatwas/5902/حكم-اخذ-الزوج-من-راتب-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_102/10201.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":9571,"question":"يقول أيضاً: إذا اشترط ولي المرأة على الزوج ألا يتزوج معها ثانية ورضي الزوج بذلك عند العقد، فهل يصح هذا الشرط؟ وهل إذا تزوج عليها يحق لها الفسخ؟","title":"حكم اشتراط عدم الزواج بأخرى في عقد الزواج","answer":"الجواب: نعم؛ الصواب أنه يصح الشرط في أصح قولي العلماء، إذا شرط عليه ألا يتزوج عليها أخرى صح الشرط؛ لأن فيه مصلحة من دون مضرة، وقد قال النبي ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج، وقال: المسلمون على شروطهم، فإذا التزم الزوج بأنه لا يتزوج عليها لزم الشرط، فإن أحب الزواج عليها فلا بأس عليه، لكن لها الخيار خيار الفسخ إلا أن تسمح فإذا سمحت بالزواج عليها فلا بأس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7737/حكم-اشتراط-عدم-الزواج-باخرى-في-عقد-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24709.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":9574,"question":"يقول أيضاً: إذا اشترط ولي المرأة على الزوج ألا يتزوج معها ثانية ورضي الزوج بذلك عند العقد، فهل يصح هذا الشرط؟ وهل إذا تزوج عليها يحق لها الفسخ؟","title":"حكم اشتراط عدم الزواج بأخرى في عقد الزواج","answer":"الجواب: نعم؛ الصواب أنه يصح الشرط في أصح قولي العلماء، إذا شرط عليه ألا يتزوج عليها أخرى صح الشرط؛ لأن فيه مصلحة من دون مضرة، وقد قال النبي ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج، وقال: المسلمون على شروطهم، فإذا التزم الزوج بأنه لا يتزوج عليها لزم الشرط، فإن أحب الزواج عليها فلا بأس عليه، لكن لها الخيار خيار الفسخ إلا أن تسمح فإذا سمحت بالزواج عليها فلا بأس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7737/حكم-اشتراط-عدم-الزواج-باخرى-في-عقد-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24709.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":11194,"question":"يقول: نريد من سماحتكم كلمة توجيهية للرجال الذين تزوجوا بأكثر من واحدة، وذلك بأن يراعوا حقوقهن، ويعدلوا بينهن؛ ذلك لأن بعض النساء يشتكين من الظلم، وعدم العدل، وهل من حق المرأة أن تطالب ببيت مستقل لها ولأولادها؟","title":"الحث على العدل بين الزوجات","answer":"الجواب:  الواجب على الزوج العدل، الواجب على الزوج العدل بين الزوجتين أو الثلاث أو الأربع، ويحرم عليه الظلم والجور، يقول النبي ﷺ: من كانت له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل فالله جل وعلا أوجب العدل على الزوج فيما يتعلق بالقسم والنفقة. أما ما لا يستطيع كالحب، وما يتبع الحب من جماع ونحو ذلك، فهذا ليس إليه، ولا يستطيعه، ولكن عليه أن يعدل في قسمته بينهم وفي النفقة، تعطى كل واحدة كفايتها حسب الطاقة، وليس له أن يجور في ذلك.  وأما كونه يجعل لها بيتًا مستقلًا؛ هذا فيه تفصيل: إذا كانت عند أهله في محل مناسب يكفي، ولو عند أهله ما يلزم أن يكون لها بيت مستقل، يجعلها عند أبويه أو عند أمه أو عند أبيه، أو في بيته هو وإخوته، في محل مناسب ليس فيه مضرة عليها فلا بأس، ليس بشرط ذلك أن تكون مستقلة، إلا إذا كان هناك شرط عند العقد، شرط عليه أنها تكون في بيت مستقل، فالمسلمون على شروطهم، إذا كان شرط عليه عند العقد أنه يجعلها في بيت مستقل فهذا لا بأس، وإلا فإنها تسكن مع أهله ومع أبويه أو مع إخوته في محل مناسب، إذا كان البيت مناسبًا يتسع للجميع. نعم. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9365/الحث-على-العدل-بين-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37210.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":14160,"question":"هذا السائل الذي رمز لاسمه بـ (م. ر. ف) من جمهورية مصر العربية- الفيوم يقول: لقد تزوجت منذ عام وبعد زواجي بشهرين اكتشفت أن زوجتي تسرق من البيت نقود ومن أمي وإخوتي، وبعد أن قمت بنصحها مرات عدة ولكن بكل أسف لم تعمل بنصيحتي، وبعد أن وعدتني بأن لا تفعل هذا الشيء مرة أخرى عادت وفعلت، والآن أنا أعمل هنا وأرسلت لأهلي وقلت لهم بأن يرسلوها لبيت والدها، وها أنا الآن لا أرغب العيش معها أبدًا بسبب هذه العادة السيئة -السرقة- وهي الآن عند أبيها منذ خمسة شهور، فهل لو طلقتها هل لها علي حقوق كالأثاث مثلًا والذهب الذي اشتريته لها؛ شبكة كما يسمونها؟","title":"هل للمرأة التي تسرق حقوق إذا طُلِّقت؟","answer":"الجواب: عليك أن تسلم لها حقوقها وجميع ما شرطته لها تعطيه إياها المسلمون على شروطهم وكونك تطلقها هذا مناسب، ما دام أنها اكتشفت أنها تسرق ولم تقبل النصيحة فإبعادها وطلاقها أفضل، ولكن ليس لك أن تأخذ شيئًا من حقها، ما شرطت لها في النكاح تعطيها إياه ولا تأخذ منه شيئًا لا من ذهب ولا من غيره المسلمون على شروطهم ويقول النبي ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج متفق على صحته. فالواجب عليك أن تعطيها حقوقها، وإذا أردت طلاقها فلا بأس؛ لسوء عملها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12601/هل-للمراة-التي-تسرق-حقوق-اذا-طلقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54622.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":15361,"question":"السائل أبو معاوية الأردن، عمان، يقول في هذا  سماحة الشيخ الراتب التي تأخذه الزوجة إذا كانت موظفة، هل هو من حقها لوحدها، أم للزوج فيه نصيب؟ بمعنى: إذا كان يترتب على عملها أن يتنازل الزوج عن بعض حقوقه؟فوجهونا بهذا السؤال.","title":"حكم أخذ الزوج من راتب زوجته","answer":"الجواب: الحكم في هذا على ما اتفقا عليه إذا اتفقا على أن النصف للزوج أو الربع أو الثلث أو أقل أو أكثر فلا بأس المسلمون على شروطهم، والصلح جائز بين المسلمين إلا صلحًا حرم حلالًا، أو أحل حرامًا فإذا اتفق معها أنها تعمل موظفة مدرسة، أو ممرضة، أو طبيبة، واتفق معها على أن له النصف أو الثلث أو الربع أو الراتب كله، فلا بأس، الحق لا يعدوهما. أما إن كان مشروطًا في العقد شرط، اشترطت عليه في العقد أن راتبها لها، وأنه يقدم على أنها موظفة، مدرسة، ممرضة، طبيبة أو غير ذلك، وأن راتبها لها، إذا شرط عليه هذا فإنه لا حظ له فيه، لا حق له، إلا بشيء تسمح به، لقوله ﷺ: المسلمون على شروطهم لكن إن سمحت بشيء فلا بأس؛ لقول الله سبحانه: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4] إذا طابت نفسها بشيء من راتبها قليل أو كثير فلا بأس، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13864/حكم-اخذ-الزوج-من-راتب-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49904.mp3","categories":["الحقوق الزوجية","الشروط والعيوب في النكاح","قضايا المرأة"]},{"id":15379,"question":"السائل يقول: هل يجوز للمرأة أن تشترط على الزوج أثناء العقد بأن لا يتزوج بالثانية؟","title":"ما حكم اشتراط المرأة عند العقد ألا يتزوج زوجها الثانية؟","answer":"الجواب: لا حرج، لا أعلم حرجًا؛ لقوله ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج المسلمون على شروطهم فإذا تزوجها على أن لا يتزوج عليها فلها شرطها، فإذا تزوج عليها فهي بالخيار، إن شاء طلق إذا طلبت وإن رغبت بالبقاء بقيت معه، لكن إذا تزوج وهي شرطت عليه يلزمه الطلاق، إلا إذا سامحته؛ لأن الرسول ﷺ قال: إن أحق الشروط أن يوفى به ما استحللتم به الفروج رواه البخاري ومسلم في الصحيحين، وقال أيضًا -عليه الصلاة والسلام-: المسلمون على شروطهم فإذا تزوجها على أن لا يتزوج عليها، ثم بدا له شاورها، فإن سمحت فلا بأس، وإلا يطلقها، نعم.","link":"https://binbaz.org.sa/fatwas/13882/ما-حكم-اشتراط-المراة-عند-العقد-الا-يتزوج-زوجها-الثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56710.mp3","categories":["الشروط والعيوب في النكاح","قضايا المرأة"]},{"id":15932,"question":"هذه السائلة (ع. أ. ع) من الجنوب تقول -سماحة الشيخ-: فتاة مقدمة على الزواج، وهي معلمة في أحد شروطها في العقد: أنها حرة التصرف في راتبها، وهي تخشى من الخلاف فيما بعد على أمر الراتب، وتود أن تعطي أهلها شيئًا من هذا الراتب، وتبقي شيئًا آخر لزوجها؛ فهل عدلت في ذلك؟ وهل تكتفي بإعطاء الزوج ألف ريال فقط، ويكون هذا من العدل؟","title":"وجوب الوفاء بالشروط التي عند عقد النكاح","answer":"الجواب: هذا يتعلق فيما بينها وبين أهلها وزوجها والمسلمون على شروطهم هي حرة في راتبها، فإذا كان بينها وبين الزوج شروط أنها لا تشتغل، أو أنها تعطيه نصف الراتب، فهم على شروطهم عند العقد، يقول النبي ﷺ: المسلمون على شروطهم إذا اتفقت مع الزوج على شرط أنها تدرس أو تعمل كذا، ويكون له نصف الراتب، ربع الراتب، فهم على شروطهم، أو سمح لها، ولم يأخذ من راتبها شيئًا فلا بأس، وهكذا مع أبيها وأمها الأمر بينهم لا يتجاوزهم إذا اتفقوا على شيء فلا حرج. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14531/وجوب-الوفاء-بالشروط-التي-عند-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57802.mp3","categories":["الشروط والعيوب في النكاح","قضايا المرأة"]},{"id":17231,"question":"سماحة الشيخ الحقيقة أمامي رسالة، من طبيبة ومعيدة في كلية الطب، قالت: أرجو عرضها على سماحة الشيخ، ضمنت الحقيقة هذه الرسالة طويلة، وضمنتها مجموعة من الأسئلة، تقول: سماحة الشيخ، حفظكم الله، تذكر بأنها امرأة متزوجة، منذ خمس سنوات تقريبًا، ولها ابنة، تقول: عند الزواج اشترط والدي على زوجي، وكتب شروطًا في العقد، على أن أكمل دراستي العليا، حيث أنها طبيبة، ومعيدة في كلية الطب، وعلى أن تشتغل قبل وبعد الدراسة، ووافق الزوج على ذلك، في مدة دراستها، تقول: كنت أصرف على نفسي، وبيتي، وابنتي، ولا أحمل زوجي أعبائي، وذلك عرفانًا مني على وقوفه بجانبي، بالرغم من أنني كنت أفضل لو نقل عمله عندي؛ لأن مسؤولية الحياة صعبة، وخصوصًا مع الدراسة، ولكن الآن زوجي يعتبر أن صرفي على نفسي هذا واجب، ونفقتي على نفسي وابنتي، وعلى البيت الذي أعيش به، من كل النواحي هي مسؤوليتي؛ لأنني لست معه، مع أنني غير موافقة، ولكن لا مانع لدي، والسؤال يا سماحة الشيخ، تقول: هل موافقة زوجي من بداية الزواج على أن أدرس، يعطيه الحق في أنه يدع مسؤوليته؟ أو مسؤولية البيت ماديًا، ومعنويًا علي بحجة أنني لست معه، رغم أنه من المفروض أن يكون هو المسؤول، وأن يكون معي؛ لأنه وافق على تكملة دراستي في منطقةٍ غير منطقة عملي، لعدم وجود جامعة تدرس الدراسات العليا هناك؟","title":"حكم النفقة على من تدرس في مكان بعيد عن الزوج","answer":"الجواب: الموافقة من الزوج على تكميلك الدراسة لا يسقط عنه النفقة، عليه نفقة البيت، وعليه نفقتك، ومالكِ لك، ومعاشك لك، لكن إذا سمحت بالمعاش، أو بعضه للزوج، أو بنفقة البيت، أو بالنفقة على نفسك؛ فلا بأس؛ لأن الله يقول سبحانه: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4] من الزوجات، فإذا سامحتيه فهو أحسن؛ حتى تبقى العشرة بينكما، والمودة بينكما، فإذا ساعدتيه في النفقة على بيتك، أو على نفسك؛ فكله طيب، وإلا فالواجب النفقة عليه هو. نعم.","link":"https://binbaz.org.sa/fatwas/16059/حكم-النفقة-على-من-تدرس-في-مكان-بعيد-عن-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59108.mp3","categories":["الشروط والعيوب في النكاح","قضايا المرأة"]},{"id":17762,"question":"يقول السائل في هذا  هل يجوز للرجل أن يشترط على المرأة أن تجري فحوصات طبية قبل الزواج، وإن كانت نتائج الفحص غير مرضية أن تكون نتائج الفحص تخبر بأن المرأة تحمل مرضًا وراثيًا مثلًا في ضعف البصر، روماتزم، فهل يحق للرجل حينئذ أن يفسخ الخطبة؟","title":"حكم اشتراط الفحوصات قبل الزواج","answer":"الجواب: لا ينبغي هذا العمل وهو طلب إجراء الفحوص؛ لأن هذا يفتح باب شر، وقد يغلط الطبيب فيسبب لها مشاكل أو للرجل مشاكل، ولكن يسأل عنها فإن كان ظاهرها أنها صحيحة وسليمة فالحمد لله وهكذا الرجل، وليس لأهل الزوجة أن يخفوا عيبها إذا كان بها مرض خفي ليس لهم أن يخفوه عليهم أن يبينوا ولا يغشوا الزوج، أما كونه يطالب بفحص من جهة الطبيب فلا أعرف لهذا أصلًا، ولا ينبغي فعل هذا؛ لأنه يسبب مشاكل، وربما أفضى إلى شر عظيم، وتعطيل النساء بغلط بعض الأطباء. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16737/حكم-اشتراط-الفحوصات-قبل-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77717.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":18204,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين السائل عطية مسعود من مكة المكرمة، أخونا يسأل ويقول: رجل زوج موليته على رجل من قبيلة أخرى، وعند الزواج طلب منه مبلغًا من المال يساوي ثمانية آلاف ريال غير المهر، ليدفعه ولي الزوجة إلى قبيلته بحكم العادة؛ حيث أن الذي تزوج ليس من القبيلة نفسها، فهم يأخذون مثل هذا المبلغ على كل من يزوج موليته خارج القبيلة، ويضعونه في صندوق القبيلة للطواري.وسؤالي هو: هل هذا جائز أم هو من قبيل المكس المحرم في الشرع؟ وبماذا تنصحون الناس؟ جزاكم الله خيرًا.","title":"حكم إلزام الخاطب بدفع مبلغ لقبيلة المخطوبة","answer":"الجواب: هذا العمل لا يجوز، أن يلزموا الخاطب من غير قبيلتهم أن يدفع للقبيلة ثمانية آلاف أو أكثر أو أقل؛ لأن هذا يسبب تعطيل النساء ولأنه أخذ مال بغير حق، المهور للمرأة، المهر للمرأة ليس للقبيلة، فلا يجوز تعاطي هذا العمل، بل هو منكر، فيجب تعطيله، ويجب على ولي الأمر في البلد التي فيها هذا أن يعطل ذلك. وإذا أرادوا أن ينفعوا أنفسهم فليبذلوا من أموالهم لما يقع بينهم من الحوادث من أموالهم، أما أن يأخذوا من أموال الناس الذين يخطبون بناتهم من غير القبيلة فهذا غلط وتنفير من الزواج وتعطيل للنساء، فالواجب منع ذلك منعًا باتًا، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/17245/حكم-الزام-الخاطب-بدفع-مبلغ-لقبيلة-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_908/nour_90803.mp3","categories":["الشروط والعيوب في النكاح"]},{"id":18520,"question":"رسالة بعثت بها إحدى الأخوات من المنطقة الشرقية الخبر تقول: (س. م. ن) أختنا ذيلت رسالتها بقولها: أرجو من سماحة الشيخ عبد العزيز بن باز التفضل بالإجابة على هذه الأسئلة، ثم بدأت رسالتها بقولها: السلام عليكم ورحمة الله وبركاته، أحييكم على جميع ما تبذلونه في هذا البرنامج لما له من منفعة عظيمة، وخير كثير. وأدعو الله أن يوفقكم، ويوفق جميع من ساهم في إعداد هذا البرنامج، أما بعد: فلدي مجموعة من الأسئلة، وأرجو أن تتفضلوا بالإجابة عليها:السؤال الأول: ما حكم أن تتزوج الفتاة من إنسان يشرب الخمر، مع العلم أنه يشرب فقط إذا أصيب بالاكتئاب والحزن، وهذا الشخص يريد من يخلصه من هذا المنكر، ويطمع في أن تكون شريكته هي من تساعده على ذلك، فما رأي سماحتكم في هذه المسألة؟","title":"حكم زواج المرأة بشارب الخمر","answer":"الجواب: أولًا: جزاك الله عن دعائك خيرًا، وتقبل منا ومنك ومن سائر المسلمين أعمالنا وأقوالنا الصالحة. أما هذا الذي يشرب الخمر فهذا لا شك أنه عيب ونقص، نسأل الله أن يمن عليه بالتوبة والهداية، ولكن لا يمنع من الزواج من المسلمة، لا بأس أن يتزوج مسلمة؛ لأن شرب الخمر لا يخرجه من دائرة الإسلام، وإنما هو معصية كبيرة، ويخرجه من دائرة العدالة إلى دائرة الفسق، ويوجب عليه الحد إذا ثبت عليه بالإقرار أو بالبينة الشرعية، ولكنه عند أهل السنة والجماعة لا يكون كافرًا، وقد ثبت عن رسول الله -عليه الصلاة والسلام- \"أنه لعن الخمر وشاربها وساقيها، وعاصرها ومعتصرها، وحاملها والمحمولة إليه، وبائعها ومشتريها، وآكل ثمنها\".  فالخمر منكر عظيم، وشره عظيم، وعواقبه وخيمة، لكنه لا يكون صاحبه كافرًا إذا لم يستحله، إذا فعله وهو يعلم أنها معصية، ويعتقد أنها معصية، ولكنه تساهل في ذلك لأسباب كثيرة، منها ما ذكرت من كونه يشرب حال الاكتئاب والتعب، ومنها أسباب أخرى. وبكل حال فهذا السبب وغيره لا يبرر له شرب الخمر، بل يجب عليه أن يحذر شرب الخمر، وأن يتعاطى الأشياء المباحة سوى ذلك، وفيما أباح الله غنية عما حرم  ولكنه لا يمنع من تزوجه على امرأة مسلمة، ولها أن تقبله ولربما هداه الله بأسبابها، فلا بأس بذلك، وعسى الله أن يجعل في ذلك خيرًا كثيرًا، ومصلحة كبيرة لهذا المسكين. المقصود: من هذا أن المعصية لا تمنع من الزواج بمسلمة، كما أنها لا تمنع المسلم أن يتزوج مسلمة فيها معصية كشرب الخمر، أو غير ذلك من الذنوب التي لا تخرج فاعلها من الإسلام، والله المستعان، نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/17630/حكم-زواج-المراة-بشارب-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_870/nour_87003.mp3","categories":["الشروط والعيوب في النكاح","قضايا المرأة"]},{"id":18529,"question":"رسالة بعثت بها إحدى الأخوات من المنطقة الشرقية الخبر تقول: (س. م. ن) أختنا ذيلت رسالتها بقولها: أرجو من سماحة الشيخ عبد العزيز بن باز التفضل بالإجابة على هذه الأسئلة، ثم بدأت رسالتها بقولها: السلام عليكم ورحمة الله وبركاته، أحييكم على جميع ما تبذلونه في هذا البرنامج لما له من منفعة عظيمة، وخير كثير. وأدعو الله أن يوفقكم، ويوفق جميع من ساهم في إعداد هذا البرنامج، أما بعد: فلدي مجموعة من الأسئلة، وأرجو أن تتفضلوا بالإجابة عليها:السؤال الأول: ما حكم أن تتزوج الفتاة من إنسان يشرب الخمر، مع العلم أنه يشرب فقط إذا أصيب بالاكتئاب والحزن، وهذا الشخص يريد من يخلصه من هذا المنكر، ويطمع في أن تكون شريكته هي من تساعده على ذلك، فما رأي سماحتكم في هذه المسألة؟","title":"حكم زواج المرأة بشارب الخمر","answer":"الجواب: أولًا: جزاك الله عن دعائك خيرًا، وتقبل منا ومنك ومن سائر المسلمين أعمالنا وأقوالنا الصالحة. أما هذا الذي يشرب الخمر فهذا لا شك أنه عيب ونقص، نسأل الله أن يمن عليه بالتوبة والهداية، ولكن لا يمنع من الزواج من المسلمة، لا بأس أن يتزوج مسلمة؛ لأن شرب الخمر لا يخرجه من دائرة الإسلام، وإنما هو معصية كبيرة، ويخرجه من دائرة العدالة إلى دائرة الفسق، ويوجب عليه الحد إذا ثبت عليه بالإقرار أو بالبينة الشرعية، ولكنه عند أهل السنة والجماعة لا يكون كافرًا، وقد ثبت عن رسول الله -عليه الصلاة والسلام- \"أنه لعن الخمر وشاربها وساقيها، وعاصرها ومعتصرها، وحاملها والمحمولة إليه، وبائعها ومشتريها، وآكل ثمنها\".  فالخمر منكر عظيم، وشره عظيم، وعواقبه وخيمة، لكنه لا يكون صاحبه كافرًا إذا لم يستحله، إذا فعله وهو يعلم أنها معصية، ويعتقد أنها معصية، ولكنه تساهل في ذلك لأسباب كثيرة، منها ما ذكرت من كونه يشرب حال الاكتئاب والتعب، ومنها أسباب أخرى. وبكل حال فهذا السبب وغيره لا يبرر له شرب الخمر، بل يجب عليه أن يحذر شرب الخمر، وأن يتعاطى الأشياء المباحة سوى ذلك، وفيما أباح الله غنية عما حرم  ولكنه لا يمنع من تزوجه على امرأة مسلمة، ولها أن تقبله ولربما هداه الله بأسبابها، فلا بأس بذلك، وعسى الله أن يجعل في ذلك خيرًا كثيرًا، ومصلحة كبيرة لهذا المسكين. المقصود: من هذا أن المعصية لا تمنع من الزواج بمسلمة، كما أنها لا تمنع المسلم أن يتزوج مسلمة فيها معصية كشرب الخمر، أو غير ذلك من الذنوب التي لا تخرج فاعلها من الإسلام، والله المستعان، نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/17630/حكم-زواج-المراة-بشارب-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_870/nour_87003.mp3","categories":["الشروط والعيوب في النكاح","قضايا المرأة"]},{"id":19104,"question":"رسالة مطولة بعض الشيء بعثت بها إحدى الأخوات المستمعات تقول: المرسلة (س. م. ج) من مكة، سأقرأ رسالتها كما وردت: بسم الله الرحمن الرحيم، الحمد لله رب العالمين والصلاة والسلام على أشرف المرسلين سيدنا محمد ﷺ وعلى آله وصحبه أجمعين والتابعين ومن تبعهم بإحسان إلى يوم الدين.سماحة الشيخ عبد العزيز بن عبد الله بن باز ! حفظه الله، السلام عليكم ورحمة الله وبركاته وبعد:أرجو من سماحتكم أن توجهوا كلمة لهذه الإنسانة البائسة الحزينة تصبرونها بها وترفعون من معنوياتها؛ حيث أنها ستموت قهرًا وحسرة وألمًا مما حدث معها.تزوجت من رجل اختارته؛ لأنه يماثلها في المستوى الثقافي والاجتماعي، فهي جامعية وهو جامعي، جاءت به محرمًا معها للعمل بالتدريس بالمملكة، واستمر زواجها سنة وتسعة أشهر، عاشت معه سنة عند أهله حيث كان خجلًا لا ينكشف عليها، وإذا أراد معاشرتها لا تلحظ منه شيئًا، وهي لا تدري ما السبب، ثم اتضح فيما بعد أنه مخصي، ولذا كان يخفي حقيقة أمره عنها، وهي تنوه إلى أنه كان متزوجًا قبلها بامرأة أيضًا، وانفصلت عنه، ولكن في الزواج الثاني نجح في اصطياد فريسته بالتضليل والغش والخداع، فعمل احتياطاته كي تعيش معه الثانية دون أن تلحظ ما به، ولكن لسوء حظه انكشف أمره في الفندق حينما كانا يجهزان للسفر للمملكة، ففكرت أن ترجع لأهلها وتبلغهم بذلك، وتنفصل عنه، ولكنها عدلت عن تلك الفكرة حيث أنها اعتقدت أن ذلك قد يتطلب منها إرجاع ما خسره عليها من تكاليف الزواج، واستمرت في رحلتها للمملكة، واستمرت معه التسعة أشهر الأخيرة، ثم في انتهاء العطلة الدراسية رفعت الدعوة للقاضي الذي فصل بينهما وأرجع للزوج منها عشرة آلاف ريال.وهي تتساءل وتقول: هل من الممكن أن نشجع الغش والخداع مع مثل هؤلاء، فنعطيهم أيضًا مكافأة غشهم وخداعهم، لقد قال رسول الله ﷺ: من غشنا فليس منا وهو لو لم يخادعها ويغشها لعاشت معه حتى لو لم ينجب الأولاد، ولكن لأنه خدعها وغشها فقد تركته غير آسفة عليه، ولكن ما قهرها هو دفعها للعشرة آلاف ريال.إنها تحس بالظلم في تلك القضية، ومثل هذا الحكم سيشجعه على الزواج من الثالثة والرابعة والخامسة.. إلى آخر، دون أن يصارحها بحقيقة أمره طالما أنه يضمن إرجاع المهر له، والعجيب في ذلك الغش أنه قد يذهب بالمرأة في متاهات مثلما حدث مع الثانية التي كانت تعتقد أن إعاقة الحمل منها، فغررت بها أمه وذهبت بها للأطباء، وادعى طبيب منهم أنه لا بد من إجراء عملية جراحية للمرأة، وفعلًا عملها لها الطبيب وهو ساكت ولم يقل الحقيقة، وأمه أيضًا تعرف ولكن لا تريد أن تثبت على ابنها شيئًا.فما رأي سماحتكم في تلك القضية؟ وماذا تقولون لهذه المظلومة؟ وماذا تقولون لأمثال هؤلاء الشبان الذين لا يصارحون زوجاتهم؟ وفقكم الله، والسلام عليكم ورحمة الله وبركاته.","title":"عيب في الزوج لم يخبر به، فما حكم النكاح؟","answer":"الجواب: لا ريب أن الخداع والغش من المحرمات المعلومة من الإسلام بالأدلة الصحيحة وبالضرورة، فالرسول عليه الصلاة والسلام قال: من غشنا فليس منا، والله يقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27]، فالواجب على الخاطب أن يبين الحقيقة، وأن لا يكتم عن المخطوبة ما هو عيب مثل هذا الحادث، بل يشرح لها الحقيقة حتى تكون على بينة، إذا كان به عيب الخصية، أو عيب آخر وهو كونه لا يأتي النساء من أجل مرض آخر أو علة أخرى، أو كونه يصرع، أو ما أشبه ذلك من العيوب المعروفة. فالواجب عليه أن يبين للمرأة الحقيقة، فإذا لم يبين فلها الخيار وليس له حق في المهر، فإذا دخل بها وخلا بها فلها المهر كله، وهو الظالم، فليس له حق في ذلك. لكن هذه دعوى منك ما نستطيع أن نحكم عليها، والقاضي الذي حكم بينكما نرجو أنه وفق للصواب، ولا ندري ما هو الشيء الذي اعتمد عليه في إلزامك بالمبلغ الذي ذكرت، فالذي أطمئنك به أنه ينبغي لك الصبر وعدم الاكتراث بهذا الشيء، واحمدي الله الذي خلصك منه، والقاضي قد يكون له اجتهاد في ذلك، وقد رأى منك ما يقتضي ذلك. فالحاصل أنصحك بأن تسلي نفسك عن هذا الشيء، وتصبري وتحتسبي، وتسألي الله للقاضي بالعفو عما حصل إذا كان أخطأ في حكمه، وما عند الله خير وأبقى، وسوف يعوضك الله سبحانه إن شاء الله عن هذا خيرًا منه، فهو جل وعلا الحكيم العليم، والمظلوم ينتظر النصر، وما ذهب من المؤمن بغير وجه شرعي، فالله يخلفه عليه  ويعوضه خيرًا، فضلًا منه وإحسانًا : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] ، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] ، فاصبري واحتسبي واسألي الله العوض من عنده  وأن يهبك زوجًا صالحًا خيرًا منه، والمال أمره سهل، الله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18292/عيب-في-الزوج-لم-يخبر-به-فما-حكم-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88404.mp3","categories":["الشروط والعيوب في النكاح"]}]
